    pub fn book_level(base: &str, quote: &str, level: u64) -> Result<serde_json::Value, String> {
        let (a, b) = super::swap_pair(base, quote)?;
        let orders = super::swap_fetch_level(a, b, level)?;
        let nullifiers: Vec<String> = orders
            .iter()
            .map(|o| hex::encode(super::pq_spend::cm_limbs_to_bytes(o.maker_nullifier)))
            .collect();
        Ok(serde_json::json!({
            "level": level,
            "orders": orders.len(),
            "nullifiers": nullifiers,
        }))
    }
    /// Create a FRESH wallet through the EXACT app path (`pq::generate` + birth-at-tip + scan reset — the same
    /// steps `wallet_generate` runs, synchronously): the new wallet's scan starts at the current tip, exactly
    /// like tapping "Create wallet" in the app. Returns `{ "seed": ..., "address": ... }`.
    pub fn generate() -> Result<serde_json::Value, String> {
        let (phrase, keys) = super::pq::generate()?;
        let address = keys.address.clone();
        let scan_ek = keys.scan_ek.clone();
        super::open_address_keys(&keys); // per-address keys: before any of this wallet's notes is opened
        *super::WALLET.lock().unwrap_or_else(|e| e.into_inner()) = Some(keys);
        // Same basis as `wallet_generate`: the note-stream position, not the chain height.
        let birth = super::probe_node(700)
            .and_then(|i| i.get("served_seq").and_then(|b| b.as_u64()))
            .unwrap_or(0);
        // DB-88: a wallet born now has no notes below the tip — its trial-decap cursor starts at the chain
        // height of its birth (Bitcoin's wallet birthday); a seed RESTORE has no birthday and scans from 0.
        let tip_h = super::probe_node(700)
            .and_then(|i| i.get("height").or_else(|| i.get("blue_score")).and_then(|b| b.as_u64()))
            .unwrap_or(0);
        super::save_applied_cursor(&super::scan_scope_id(&scan_ek), tip_h, None);
        super::WALLET_BIRTH.store(birth, super::Ordering::SeqCst);
        super::reset_scan(&scan_ek, birth);
        // DB-279 §7: the same birth record the app's create path writes (one helper, both generate doors).
        super::record_generated_birth(&scan_ek, tip_h)?;
        // The address a fresh wallet publishes vs the key it will actually SCAN with. A mismatch means every
        // payment to that address is sealed to a key this wallet never tries — delivered, recorded, replicated
        // and permanently invisible to its owner. DIGITAL-CASH-PRIVACY-REVIEWED: public ek fingerprints only.
        let published_fp = super::pq::parse_address(&address)
            .map(|(_, _, ek)| super::ek_fp(&ek))
            .unwrap_or_else(|| "UNPARSEABLE".to_string());
        eprintln!(
            "[wallet_generate] published address ek fp {published_fp}, this wallet scans with fp {}",
            super::ek_fp(&scan_ek)
        );
        // ⛔ A GENERATED WALLET MUST SURVIVE THE PROCESS THAT MADE IT.
        //
        // `generate()` returned the seed to the caller and wrote it NOWHERE, so the next launch against the
        // same data dir was a DIFFERENT wallet with a different address. Funds sent to the first address are
        // then unreachable by the second — the money is on chain, the seed is gone, and nothing reports an
        // error. It cost two runs of this session directly: an address was funded, the next invocation minted
        // a fresh wallet, and the sends that followed ran on an empty one.
        //
        // A real user tapping "Create wallet" expects to still own it after closing the app. Writing the seed
        // beside the note store is what makes the data dir mean "this wallet" instead of "whatever was made
        // last". Written 0600 — it is the spending key, and the file must not be world-readable.
        super::persist_seed_phrase(&phrase);
        Ok(serde_json::json!({ "seed": phrase, "address": address }))
    }
