        // publishes the content key under the vault's own pad instead (`delivery_claim_tag`).
        let lock_claim = match &vault {
            VaultSend::Take { note, secret, deliver: Some(_), .. } => {
                let tag = usdm_decider::whir_rec_block::delivery_claim_tag(note, secret);
                Some((tag, tag, tag))
            }
            VaultSend::Take { note, branch, secret, .. } if *branch != VaultBranch::Clock => {
                Some(usdm_decider::whir_rec_block::vault_lock_claim(&keys.spk, secret, &note.opening()))
            }
            _ => None,
        };
