        // DB-329 §7f: a note-class send's two REAL rows are its nullifier and its claim tag.
        let padded_nfs = aligned_padded_tags_of(&[nfb, usdmd_node::spend_frontier::leaf_to_cm_bytes(t1)], &tx_secret);
        let nullifiers_hex = {
            let mut out = String::with_capacity(padded_nfs.len() * 64);
            for t in &padded_nfs {
                out.push_str(&hex::encode(t));
            }
            out
        };
