/// ⭐ §BR-11 lever 2 — "BOND MY REWARDS". One switch, OFF by default (bonding is the holder's choice): while ON, every mining
/// reward this wallet's node seals to it goes straight into this wallet's SAT custody bond (a first bond, or a top-up of the
/// seated one) instead of the spendable balance — the SAME `bond_sat_impl` the Bond button runs, one reward note per step.
/// The rewards stay the wallet's own (unbond any time; the governed unbonding window, 21 days by default). Persisted per
/// device beside the note store; absent = OFF.
fn bond_rewards_on() -> bool {
    std::fs::read_to_string(node_data_dir().join("bond-rewards")).is_ok_and(|s| s.trim() == "on")
}

#[tauri::command]
fn wallet_bond_rewards() -> Result<serde_json::Value, String> {
    Ok(serde_json::json!({ "on": bond_rewards_on() }))
}

fn wallet_set_bond_rewards_blocking(on: bool) -> Result<serde_json::Value, String> {
    let dir = node_data_dir();
    let _ = std::fs::create_dir_all(&dir);
    std::fs::write(dir.join("bond-rewards"), if on { "on" } else { "off" }).map_err(|e| format!("could not save Bond my rewards: {e}"))?;
    Ok(serde_json::json!({ "on": bond_rewards_on() }))
}
/// Turning it ON is consent for every later reward bond, so the app's command passes the wallet's own approval naming the
/// cost and the lock first (the UI shows the same terms in its popup); turning it OFF needs none.
#[tauri::command]
async fn wallet_set_bond_rewards(on: bool) -> Result<serde_json::Value, String> {
    tauri::async_runtime::spawn_blocking(move || {
        if on && !bond_rewards_on() {
            require_user_approval(BOND_REWARDS_TERMS.to_string())?; // DB-373: fails closed
        }
        wallet_set_bond_rewards_blocking(on)
    })
    .await
    .map_err(|e| format!("wallet_set_bond_rewards task failed: {e}"))?
}

const BOND_REWARDS_TERMS: &str = "Bond my rewards: each SAT your node mines goes straight into your validator custody bond \
     instead of your spendable balance. Network fee $0.00 — no USDm is spent. Bonded SAT earns the bonders' share (25%) of \
     every network fee, paid weekly. Your rewards stay yours: unbond any time — unbonding takes 21 days.";

/// Where this wallet's mining rewards were last located (record ordinal, slot) — the `"sat"` sweep's answer. CACHE-ONLY.
static REWARD_POSITIONS: Mutex<Option<std::collections::HashSet<(u64, u8)>>> = Mutex::new(None);

/// ⭐ A REWARD POSITION IS A CHAIN FACT — THE SET ONLY GROWS (lane funds-brb29, 2026-11-01). Every complete SAT-domain sweep
/// adds the (fold ordinal, slot) pairs it located; none removes any. MEASURED (usdmw_sim_w1_14295/wallet-stderr.log, the
/// tier-1 journey on main @ cd68e9e): the sweep answered "[0,8) and matched 0 mining reward(s)" 36 times between passes that
/// matched 140–357 — a lagging index page, complete but short — and each such pass REPLACED the set with the empty one, so
/// "Bond my rewards" found no reward to bond on every refresh for 832 s (T3 red) while the wallet held 11.74 SAT of rewards.
/// ROOT-LAYER: this is the set's one writer; the readers (`reward_note_to_bond`) are unchanged.
/// MUST-STAY-GREEN: the reward provisioning pins, `bond_rewards_step`'s pick (a note still needs its position in `da_pos`).
fn note_reward_positions(found: impl IntoIterator<Item = (u64, u8)>) {
    let mut g = REWARD_POSITIONS.lock().unwrap_or_else(|e| e.into_inner());
    let set = g.get_or_insert_with(std::collections::HashSet::new);
    set.extend(found);
}
static BOND_REWARDS_IN_FLIGHT: AtomicBool = AtomicBool::new(false);

/// The reward note the next "Bond my rewards" step moves: a spendable SAT note this wallet holds at a located reward
/// position (the largest, so the bond grows fastest). Pure over its inputs.
fn reward_note_to_bond(
    owned: &[OwnedNote],
    pos: &std::collections::HashMap<[u8; 32], (u64, u8)>,
    rewards: &std::collections::HashSet<(u64, u8)>,
    spendable: impl Fn(&OwnedNote) -> bool,
) -> Option<(u64, Digest4)> {
    let sat_tag = usdmd_node::satoshi::asset_tag();
    owned
        .iter()
        .filter(|n| n.asset == sat_tag && n.amount > 0 && spendable(n))
        .filter(|n| n.note.get(..32).and_then(|c| <[u8; 32]>::try_from(c).ok()).and_then(|cm| pos.get(&cm)).is_some_and(|p| rewards.contains(p)))
        .max_by_key(|n| n.amount)
        .map(|n| (n.amount, n.seed))
}

/// ONE "Bond my rewards" step, after a detection pass (the app's background pass and the harness's synchronous refresh):
/// if the switch is ON and a reward note is spendable, bond it. Non-fatal: a refusal is logged; the next pass tries again.
fn bond_rewards_step() -> Option<serde_json::Value> {
    if !bond_rewards_on() || BOND_REWARDS_IN_FLIGHT.swap(true, Ordering::SeqCst) {
        return None;
    }
    let pick = {
        let rewards_known = REWARD_POSITIONS.lock().unwrap_or_else(|e| e.into_inner()).clone();
        let rewards = match &rewards_known {
            Some(r) => r.clone(),
            None => std::collections::HashSet::new(),
        };
        let held = PROVEN_SPENT.lock().unwrap_or_else(|e| e.into_inner()).clone();
        let s = SCAN.lock().unwrap_or_else(|e| e.into_inner());
        let pick = s.as_ref().and_then(|st| {
            reward_note_to_bond(&st.owned, &st.da_pos, &rewards, |n| spendable_now(&st.spent, &st.pending_change, &held, n.amount, n.seed, &n.nf))
        });
        if pick.is_none() {
            // ⭐ THE STEP SAYS WHY IT BONDED NOTHING (lane funds-brb29). MEASURED: the tier-1 journey's T3 "Bond my rewards never put a
            // mining reward into the bond … within 832 s" on main @ cd68e9e with W1 holding 11.74 SAT — this step ran on every
            // refresh and returned None silently, so the cause could not be read from any log. Counts of this wallet's own notes
            // on its own stderr, nothing else. DIGITAL-CASH-PRIVACY-REVIEWED: counts and a yes/no — no note, position, key or amount.
            let sat_tag = usdmd_node::satoshi::asset_tag();
            let (sat, positioned, in_rewards, spendable) = match s.as_ref() {
                Some(st) => {
                    let sat: Vec<&OwnedNote> = st.owned.iter().filter(|n| n.asset == sat_tag && n.amount > 0).collect();
                    let pos_of = |n: &OwnedNote| n.note.get(..32).and_then(|c| <[u8; 32]>::try_from(c).ok()).and_then(|cm| st.da_pos.get(&cm).copied());
                    let positioned = sat.iter().filter(|n| pos_of(n).is_some()).count();
                    let in_rewards = sat.iter().filter(|n| pos_of(n).is_some_and(|p| rewards.contains(&p))).count();
                    let spendable = sat.iter().filter(|n| spendable_now(&st.spent, &st.pending_change, &held, n.amount, n.seed, &n.nf)).count();
                    (sat.len(), positioned, in_rewards, spendable)
                }
                None => (0, 0, 0, 0),
            };
            eprintln!(
                "[bond-rewards] nothing to bond this pass: {sat} SAT note(s) owned, {positioned} with a known position, {in_rewards} at a located reward position, {spendable} spendable; reward positions {} ({} located)",
                if rewards_known.is_some() { "known" } else { "NOT KNOWN in this process (no complete SAT sweep yet)" },
                rewards.len()
            );
        }
        pick
    };
    let out = pick.map(|(amount, seed)| match bond_sat_impl(amount, Some(seed)) {
        Ok(r) => {
            // DIGITAL-CASH-PRIVACY-REVIEWED: this wallet's own action on its own device's stderr, sent nowhere.
            eprintln!("[bond-rewards] a mining reward went into the custody bond");
            r
        }
        Err(e) => {
            eprintln!("[bond-rewards] not bonded this pass: {e}");
            serde_json::json!({ "error": e })
        }
    });
    BOND_REWARDS_IN_FLIGHT.store(false, Ordering::SeqCst);
    out
}

// ⭐⭐⭐ §BR-3 17.3 — DELEGATED SAT BONDS, THE HOLDER'S ONE-TAP SIDE (`usdmd_node::sat_delegation_tx`). Delegating burns SAT into
// a validator's delegated colour, undelegating burns that into the unbonding colour, and releasing turns a matured unbonding
// note back into SAT — each one conversion object the block carries and every node decides at its fold. The wallet keeps
// NOTHING about a delegation: its notes' tags name the validator id and the maturity epoch, and the node's one public list
// (`/get_delegation_targets`, the same bytes for every asker) is all a seed restore needs to read them back.

/// The node's delegation targets `(id, seated)`, its governed unbonding window, the tip's blue score and the bonders' yield
/// index (§17.6).
struct DelegationView {
    targets: Vec<([u8; 32], bool)>,
    /// §22 3: each listed validator's uptime `(active, windows)` a delegation to it is paid at (the chain's public record).
    uptime: std::collections::HashMap<[u8; 32], (u64, u64)>,
    /// Each seated target's public custody weight (base units), for the card's list (R7 F10).
    bonds: std::collections::HashMap<[u8; 32], u64>,
    /// A-F60: the unbonding window in CHAIN TICKS (the node's `unbond_window_ticks`), and the tip's tick beside it — a
    /// delegation's maturity is a time on the chain's clock, never blocks at an assumed pace.
    window: u64,
    tip_tick: u64,
    y: u128,
}

impl DelegationView {
    /// §22 3: the uptime a delegation to `vid` is paid at — `(0, 1)` for a validator the node does not list (it earns nothing).
    fn uptime_of(&self, vid: &[u8; 32]) -> (u64, u64) {
        self.uptime.get(vid).copied().filter(|u| u.1 > 0).map_or((0, 1), |u| u)
    }
    /// What `amount` delegated to `vid` since index `y0` has earned now: the index rise weighted by the validator's uptime.
    fn earned(&self, amount: u64, vid: &[u8; 32], y0: u128) -> u64 {
        let (active, windows) = self.uptime_of(vid);
        usdmd_node::validator_activity::uptime_split(usdmd_node::peg::bond_yield_between(u128::from(amount), y0, self.y), active, windows).0
    }
}

fn delegation_view() -> Result<DelegationView, String> {
    let r: serde_json::Value = ureq::AgentBuilder::new()
        .timeout(Duration::from_secs(10))
        .build()
        .get(&format!("{}/get_delegation_targets", node_url()))
        .call()
        .map_err(|e| format!("cannot read the validators you can delegate to (nothing was spent): {}", node_refusal(e)))?
        .into_json()
        .map_err(|e| format!("the delegation list is unreadable (nothing was spent): {e}"))?;
    let rows = r.get("targets").and_then(|v| v.as_array()).ok_or("the node served no delegation list (nothing was spent)")?;
    let parse = |t: &serde_json::Value| -> Option<([u8; 32], bool, u64)> {
        let id = hex::decode(t.get("id")?.as_str()?).ok()?;
        Some((<[u8; 32]>::try_from(id.as_slice()).ok()?, t.get("seated")?.as_bool()?, t.get("bond").and_then(|b| b.as_u64()).unwrap_or(0)))
    };
    let parsed: Vec<([u8; 32], bool, u64)> = rows.iter().filter_map(parse).collect();
    let uptime = rows
        .iter()
        .filter_map(|t| {
            let id = <[u8; 32]>::try_from(hex::decode(t.get("id")?.as_str()?).ok()?.as_slice()).ok()?;
            Some((id, (t.get("uptime_active")?.as_u64()?, t.get("uptime_windows")?.as_u64()?)))
        })
        .collect();
    let targets = parsed.iter().map(|(id, s, _)| (*id, *s)).collect();
    let bonds = parsed.iter().filter(|(_, s, _)| *s).map(|(id, _, b)| (*id, *b)).collect();
    Ok(DelegationView {
        targets,
        uptime,
        bonds,
        window: r.get("unbond_window_ticks").and_then(|v| v.as_u64()).ok_or("the node named no unbonding window (nothing was spent)")?,
        tip_tick: r.get("tip_tick").and_then(|v| v.as_u64()).ok_or("the node named no chain tick (nothing was spent)")?,
        y: r
            .get("bond_yield_index")
            .and_then(|v| v.as_str())
            .and_then(|s| s.parse::<u128>().ok())
            .ok_or("the node named no bonders' yield index (nothing was spent)")?,
    })
}

/// What one of this wallet's SAT-family notes is: delegated to a validator (settled at a yield index), or unbonding.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum SatColour {
    Delegated([u8; 32], u128),
    Unbonding(u64),
}

/// ⭐ §17.6 — THE SETTLED INDEX A DELEGATED NOTE RECORDS, in its DB-288 self-note KEM record: `y0 (16 LE) ‖ check (16)`,
/// `check = blake3("MUSD/delegation-y0/v1" ‖ y0)[..16]`, so a note without this record (pseudorandom) never reads as one.
fn delegation_record(y0: u128) -> [u8; 32] {
    let mut m = [0u8; 32];
    m[..16].copy_from_slice(&y0.to_le_bytes());
    let mut h = blake3::Hasher::new();
    h.update(b"MUSD/delegation-y0/v1");
    h.update(&y0.to_le_bytes());
    m[16..].copy_from_slice(&h.finalize().as_bytes()[..16]);
    m
}
fn delegation_record_y0(m: &[u8; 32]) -> Option<u128> {
    let y0 = u128::from_le_bytes(<[u8; 16]>::try_from(&m[..16]).ok()?);
    (delegation_record(y0) == *m).then_some(y0)
}

/// This wallet's spendable delegated and unbonding notes: `(amount, seed, colour)`. A delegated note is read from its own
/// record (its locator from the `cm → locator` bridge every located note fills) and matched against the public id list;
/// an unbonding note against the epochs since genesis (`0 ..= (tip + window) / epoch + 1`, one blake3 each).
fn my_sat_colour_notes(v: &DelegationView) -> Vec<(u64, Digest4, SatColour)> {
    use usdmd_node::sat_delegation_tx::{delegated_tag, unbonding_epoch, unbonding_tag};
    let e = unbonding_epoch(v.window);
    let unbonding: std::collections::HashMap<[u64; 3], u64> =
        (0..=(v.tip_tick.saturating_add(v.window) / e + 1)).map(|k| (unbonding_tag(k * e), k * e)).collect();
    let (Ok(dk), Some((spk, out_sk))) = (
        own_scan_dk(),
        WALLET.lock().unwrap_or_else(|x| x.into_inner()).as_ref().map(|w| (w.note_keys().spk, w.out_sk)),
    ) else {
        return Vec::new();
    };
    let bridge = LOC_BY_CM.lock().unwrap_or_else(|x| x.into_inner()).clone();
    let held = PROVEN_SPENT.lock().unwrap_or_else(|x| x.into_inner()).clone();
    let s = SCAN.lock().unwrap_or_else(|x| x.into_inner());
    let Some(st) = s.as_ref() else { return Vec::new() };
    let sat = usdmd_node::satoshi::asset_tag();
    st.owned
        .iter()
        .filter(|n| n.amount > 0 && n.asset != [0, 0, 0] && n.asset != sat)
        .filter(|n| spendable_now(&st.spent, &st.pending_change, &held, n.amount, n.seed, &n.nf))
        .filter_map(|n| {
            if let Some(m) = unbonding.get(&n.asset) {
                return Some((n.amount, n.seed, SatColour::Unbonding(*m)));
            }
            let cm = <[u8; 32]>::try_from(n.note.get(..32)?).ok()?;
            let (dom, j) = bridge.get(&cm)?;
            let y0 = delegation_record_y0(&pq::open_self_note_record(&n.note, &dk, &spk, &out_sk, dom, *j)?)?;
            v.targets
                .iter()
                .find(|(id, _)| delegated_tag(id, y0) == n.asset)
                .map(|(id, _)| (n.amount, n.seed, SatColour::Delegated(*id, y0)))
        })
        .collect()
}

/// ⭐ THE ONE BUILDER: burn `amount` of the input note `(value_in, seed)` (tag `kind`'s input) into the burn bound to a freshly
/// minted note of `kind`'s output tag sealed to this wallet, change back in the input tag, and — for an Undelegate or a Claim —
/// the bonders' yield as one USDm note (§17.6). Every self-note takes a reserved `chg` index and its DB-288 record: the
/// minted delegated note records its settled index (a seed restore reads it back), every other note the input it consumes.
fn sat_delegation_submit(
    kind: usdmd_node::sat_delegation_tx::DelegationKind,
    amount: u64,
    input: (u64, Digest4),
    // §22 3: the delegated validator's uptime a yield kind is weighted by — `(0, 0)` for a kind that pays none
    uptime: (u64, u64),
) -> Result<serde_json::Value, String> {
    use usdm_decider::whir_rec_block::{asset_note_cm, prove_asset_bond_validity_carrier_bytes, prove_asset_mint_validity_bytes};
    use usdmd_node::sat_delegation_tx::{delegation_burn_opening, DelegationKind, SatDelegationTx};
    let (value_in, in_seed) = input;
    if amount == 0 || amount > value_in {
        return Err("enter a positive amount no larger than the note — nothing was spent".into());
    }
    let (my_ek, loc_sk, out_sk, keys) = {
        let g = WALLET.lock().unwrap_or_else(|e| e.into_inner());
        let w = g.as_ref().ok_or_else(|| "no wallet open".to_string())?;
        (w.scan_ek.clone(), w.loc_sk, w.out_sk, w.note_keys())
    };
    let view = keys.view();
    let mut probe = SatDelegationTx {
        kind,
        amount,
        nullifier: [0; 32],
        leaf_commit: [0; 32],
        burn_carrier: vec![],
        membership_carrier: vec![],
        membership_tip: vec![],
        change_note: vec![],
        change_clue: vec![],
        minted_note: vec![],
        mint_carrier: vec![],
        minted_clue: vec![],
        yield_note: vec![],
        yield_carrier: vec![],
        yield_clue: vec![],
        uptime,
    };
    let (tag_in, tag_out) = probe.tags();
    let yield_amt = probe.yield_amount();
    let in_owner = keys.owner(in_seed);
    let input_nf = pq_spend::note_nullifier_asset(value_in, &in_owner, tag_in);
    let change = value_in - amount;
    let in_note = {
        let s = SCAN.lock().unwrap_or_else(|e| e.into_inner());
        s.as_ref()
            .and_then(|st| st.owned.iter().find(|n| n.amount == value_in && n.seed == in_seed).map(|n| n.note.clone()))
            .ok_or("the input note is not in this wallet — nothing was spent")?
    };
    // the reserved `chg` indices: the minted note, then the change and the yield when non-zero
    let need = 1 + usize::from(change > 0) + usize::from(yield_amt > 0);
    let reservation = reserve_chg_indices(need, &[input_nf])?;
    let mut idx = reservation.indices.iter().copied();
    let dom = chg_domain();
    let j_minted = idx.next().ok_or("no index reserved — nothing was spent")?;
    let j_change = if change > 0 { idx.next() } else { None };
    let j_yield = if yield_amt > 0 { idx.next() } else { None };
    // the minted note: a delegated colour records its settled index; any other colour the input it consumes
    let minted_record = match kind {
        DelegationKind::Delegate { y0, .. } => delegation_record(y0),
        DelegationKind::Claim { y_now, .. } => delegation_record(y_now),
        _ => input_nf,
    };
    let (minted_note, minted_opening) =
        pq::seal_self_note_with_record(&my_ek, &keys.spk, amount, tag_out, &out_sk, &minted_record, &dom, j_minted)
            .ok_or("could not seal the converted note — nothing was spent")?;
    let (mint_carrier, minted_cm) =
        prove_asset_mint_validity_bytes(amount, tag_out, &minted_opening).ok_or("the converted note's carrier did not prove — nothing was spent")?;
    let minted_cm_bytes = leaf4_to_bytes(minted_cm);
    if minted_note[..32] != minted_cm_bytes[..] {
        return Err("refusing: the converted note is not its carrier's — nothing was spent".into());
    }
    let my_dk = own_scan_dk()?;
    let (change_note, change_opening) = match j_change {
        Some(j) => pq::seal_change_with_record(&my_ek, &keys.spk, &in_note, &my_dk, change, &out_sk, &input_nf, &dom, j),
        None => pq::seal_note_full_asset(&my_ek, &keys.spk, 0, tag_in),
    }
    .ok_or("could not seal the change — nothing was spent")?;
    let change_seed = pq::scan_note_full(&change_note, &my_dk, &keys.spk)
        .filter(|(amt, _)| *amt == change)
        .map(|(_, seed)| seed)
        .ok_or("the sealed change does not open to this wallet at its amount — nothing was spent")?;
    let lc_blind = usdm_decider::whir_rec_block::fresh_lc_blind().ok_or("no entropy for the cross-bind blind — nothing was spent")?;
    let w = usdmd_node::sat_bond_tx::bond_witness(
        value_in,
        in_owner,
        amount,
        delegation_burn_opening(&minted_cm_bytes),
        change_opening,
        lc_blind,
        tag_in,
    )
    .ok_or("the burn witness does not build — nothing was spent")?;
    let (burn_carrier, cms, nf, leaf_commit) =
        prove_asset_bond_validity_carrier_bytes(&w, amount).ok_or("the burn carrier did not prove — nothing was spent")?;
    let nfb = leaf4_to_bytes(nf);
    if nfb != input_nf || change_note[..32] != leaf4_to_bytes(cms[1])[..] {
        return Err("refusing: the burn's nullifier or change is not this conversion's — nothing was spent".into());
    }
    let cm_in = leaf4_to_bytes(asset_note_cm(value_in, tag_in, in_owner.opening()));
    let agent = ureq::AgentBuilder::new().timeout(Duration::from_secs(30)).build();
    let (membership_carrier_hex, membership_tip_hex) = membership_bind_for(&agent, &cm_in, nf, lc_blind)
        .ok_or("the note's membership cannot be proved yet (its member leg is not ready) — nothing was spent")?;
    // §17.6: the yield note, USDm, sealed to this wallet
    let yield_parts = match j_yield {
        Some(j) => {
            let (note, opening) = pq::seal_self_note_with_record(&my_ek, &keys.spk, yield_amt, [0, 0, 0], &out_sk, &input_nf, &dom, j)
                .ok_or("could not seal the yield note — nothing was spent")?;
            let (carrier, cm) = prove_asset_mint_validity_bytes(yield_amt, [0, 0, 0], &opening)
                .ok_or("the yield note's carrier did not prove — nothing was spent")?;
            if note[..32] != leaf4_to_bytes(cm)[..] {
                return Err("refusing: the yield note is not its carrier's — nothing was spent".into());
            }
            Some((note, carrier, leaf4_to_bytes(cm)))
        }
        None => None,
    };
    // every note's clue at its reserved index (a zero change takes the void locator: nothing to find)
    let change_cm = leaf4_to_bytes(cms[1]);
    let mut cms_list = vec![minted_cm_bytes, change_cm];
    let mut slots = vec![Some(j_minted), j_change];
    if let (Some((_, _, ycm)), Some(j)) = (&yield_parts, j_yield) {
        cms_list.push(*ycm);
        slots.push(Some(j));
    }
    let recs = self_note_clue_records(&loc_sk, &cms_list, &slots);
    let mut clues = Vec::new();
    let mut at = 0usize;
    while at + 34 <= recs.len() {
        let len = u16::from_le_bytes([recs[at + 32], recs[at + 33]]) as usize;
        clues.push(recs.get(at + 34..at + 34 + len).ok_or("a note's clue could not be derived — nothing was spent")?.to_vec());
        at += 34 + len;
    }
    if clues.len() != cms_list.len() {
        return Err("a note's clue could not be derived — nothing was spent".into());
    }
    probe.nullifier = nfb;
    probe.leaf_commit = leaf4_to_bytes(leaf_commit);
    probe.burn_carrier = burn_carrier;
    probe.membership_carrier = hex::decode(&membership_carrier_hex).map_err(|e| format!("member leg hex: {e}"))?;
    probe.membership_tip = hex::decode(&membership_tip_hex).map_err(|e| format!("member tip hex: {e}"))?;
    probe.change_note = change_note.to_vec();
    probe.change_clue = clues[1].clone();
    probe.minted_note = minted_note.to_vec();
    probe.mint_carrier = mint_carrier;
    probe.minted_clue = clues[0].clone();
    if let Some((note, carrier, _)) = yield_parts {
        probe.yield_note = note.to_vec();
        probe.yield_carrier = carrier;
        probe.yield_clue = clues[2].clone();
    }
    if !probe.carriers_verify() {
        return Err("refusing: the conversion does not verify against its own carriers — nothing was spent".into());
    }
    let reply: serde_json::Value = agent
        .post(&format!("{}/submit_sat_delegation", node_url()))
        .send_json(serde_json::json!({ "object_hex": hex::encode(probe.encode()) }))
        .map_err(|e| format!("the node refused the conversion: {}", node_refusal(e)))
        .and_then(|r| r.into_json().map_err(|e| format!("conversion reply json: {e}")))?;
    let published = reply.get("verdict").and_then(|v| v.as_str()) == Some("PUBLISHED");
    if published {
        reservation.commit(input_nf);
        replace_input_with_remainder(&view, (value_in, in_seed), change, &change_note, change_seed);
    }
    Ok(serde_json::json!({
        "verdict": reply.get("verdict").cloned().unwrap_or("UNKNOWN".into()),
        "sat": amount as f64 / 1e8,
        "yield_usdm": yield_amt as f64 / 1e8,
        "detail": reply.get("detail").cloned().unwrap_or("".into()),
    }))
}

/// ⭐ §BR-3 17.5 layer 1 — THE REPAYMENT POT'S PUBLIC FIGURES (after a custody theft): the SAT it holds, its floor price in
/// USDm per SAT, and the USDm its sales still owe the supply. `{ "pot_sat": 0, … }` when no theft ever happened.
fn wallet_repayment_pot_blocking() -> Result<serde_json::Value, String> {
    let agent = ureq::AgentBuilder::new().timeout(Duration::from_secs(8)).build();
    let v: serde_json::Value = agent
        .post(&format!("{}/repayment_pot", node_url()))
        .send_json(serde_json::json!({}))
        .map_err(|e| format!("repayment pot: {}", node_refusal(e)))?
        .into_json()
        .map_err(|e| format!("repayment pot json: {e}"))?;
    let pot = v["pot_sat"].as_u64().unwrap_or(0);
    let scale = v["scale"].as_u64().unwrap_or(1).max(1) as f64;
    let floor = v["floor"].as_str().and_then(|f| f.parse::<f64>().ok());
    // USDm per whole SAT at the floor: floor (USDm-atomic per SAT-atomic × scale) × 1e8 SAT-atomic / scale / 1e8 USDm-atomic
    Ok(serde_json::json!({
        "pot_sat": pot as f64 / 1e8,
        "floor_usdm_per_sat": floor.map(|f| f / scale),
        "owed_usdm": v["owed_usdm_atomic"].as_u64().unwrap_or(0) as f64 / 1e8,
    }))
}
off_ui_thread!(wallet_repayment_pot => wallet_repayment_pot_blocking());

/// ⭐ §BR-3 17.5 layer 1 — BUY SAT FROM THE REPAYMENT POT AT THE FLOOR: burn `usdm` of this wallet's USDm (one covering note,
/// the flat network fee paid from it) for the SAT the floor allows, sealed to this wallet, change back to it. The request goes
/// to custody, which retires the burned USDm and frames the fill; the input stays unspent until a block carries the fill.
fn wallet_pot_buy_blocking(usdm: f64) -> Result<serde_json::Value, String> {
    use usdm_decider::whir_rec_block::{self as wr, asset_note_cm, prove_asset_mint_validity_bytes};
    let x = usdm_to_atomic(usdm)?;
    let agent = ureq::AgentBuilder::new().timeout(Duration::from_secs(30)).build();
    let v: serde_json::Value = agent
        .post(&format!("{}/repayment_pot", node_url()))
        .send_json(serde_json::json!({}))
        .map_err(|e| format!("repayment pot: {}", node_refusal(e)))?
        .into_json()
        .map_err(|e| format!("repayment pot json: {e}"))?;
    let floor = v["floor"].as_str().and_then(|f| f.parse::<u128>().ok()).filter(|f| *f > 0).ok_or("the pot is not offered (SAT is unpriced) — nothing was spent")?;
    let scale = u128::from(v["scale"].as_u64().unwrap_or(1).max(1));
    let pot = v["pot_sat"].as_u64().unwrap_or(0);
    let s_out = u64::try_from(u128::from(x) * scale / floor).map_err(|_| "the amount does not fit")?.min(pot);
    if s_out == 0 {
        return Err("the pot holds no SAT, or the amount buys less than one SAT unit — nothing was spent".into());
    }
    let fee = wr::PROTOCOL_FEE_ATOMIC;
    let (my_ek, loc_sk, out_sk, keys) = {
        let g = WALLET.lock().unwrap_or_else(|e| e.into_inner());
        let w = g.as_ref().ok_or_else(|| "no wallet open".to_string())?;
        (w.scan_ek.clone(), w.loc_sk, w.out_sk, w.note_keys())
    };
    let (value_in, in_seed, in_note) = {
        let s = SCAN.lock().unwrap_or_else(|e| e.into_inner());
        s.as_ref()
            .and_then(|st| st.owned.iter().filter(|n| n.asset == [0, 0, 0] && n.amount >= x + fee).min_by_key(|n| n.amount).map(|n| (n.amount, n.seed, n.note.clone())))
            .ok_or("no single USDm note covers the amount and the network fee — nothing was spent")?
    };
    let in_owner = keys.owner(in_seed);
    let input_nf = pq_spend::note_nullifier_asset(value_in, &in_owner, [0, 0, 0]);
    let change = value_in - fee - x;
    let reservation = reserve_chg_indices(1 + usize::from(change > 0), &[input_nf])?;
    let mut idx = reservation.indices.iter().copied();
    let dom = chg_domain();
    let j_sat = idx.next().ok_or("no index reserved — nothing was spent")?;
    let j_change = if change > 0 { idx.next() } else { None };
    let sat_tag = usdmd_node::satoshi::asset_tag();
    let (sat_note, sat_opening) = pq::seal_self_note_with_record(&my_ek, &keys.spk, s_out, sat_tag, &out_sk, &input_nf, &dom, j_sat)
        .ok_or("could not seal the SAT note — nothing was spent")?;
    let (sat_carrier, sat_cm) = prove_asset_mint_validity_bytes(s_out, sat_tag, &sat_opening).ok_or("the SAT note's carrier did not prove — nothing was spent")?;
    let sat_cm_bytes = leaf4_to_bytes(sat_cm);
    if sat_note[..32] != sat_cm_bytes[..] {
        return Err("refusing: the SAT note is not its carrier's — nothing was spent".into());
    }
    let my_dk = own_scan_dk()?;
    let (change_note, change_opening) = match j_change {
        Some(j) => pq::seal_change_with_record(&my_ek, &keys.spk, &in_note, &my_dk, change, &out_sk, &input_nf, &dom, j),
        None => pq::seal_note_full_asset(&my_ek, &keys.spk, 0, [0, 0, 0]),
    }
    .ok_or("could not seal the change — nothing was spent")?;
    let lc_blind = wr::fresh_lc_blind().ok_or("no entropy for the cross-bind blind — nothing was spent")?;
    let w = wr::SpendValidityWitness {
        value_in,
        owner: in_owner,
        value_out: value_in - fee,
        fee,
        lc_blind,
        out0_value: x,
        out0_opening: usdmd_node::pot_fill_tx::pot_burn_opening(&sat_cm_bytes),
        out1_value: change,
        out1_opening: change_opening,
    };
    let (burn_carrier, cms, nf, leaf_commit) = wr::prove_bond_validity_carrier_with_commit_bytes(&w, x).ok_or("the burn carrier did not prove — nothing was spent")?;
    if leaf4_to_bytes(nf) != input_nf || change_note[..32] != leaf4_to_bytes(cms[1])[..] {
        return Err("refusing: the burn's nullifier or change is not this buy's — nothing was spent".into());
    }
    let cm_in = leaf4_to_bytes(asset_note_cm(value_in, [0, 0, 0], in_owner.opening()));
    let (mem_hex, tip_hex) = membership_bind_for(&agent, &cm_in, nf, lc_blind).ok_or("the note's membership cannot be proved yet — nothing was spent")?;
    let change_cm = leaf4_to_bytes(cms[1]);
    let recs = self_note_clue_records(&loc_sk, &[sat_cm_bytes, change_cm], &[Some(j_sat), j_change]);
    let mut clues = Vec::new();
    let mut at = 0usize;
    while at + 34 <= recs.len() {
        let len = u16::from_le_bytes([recs[at + 32], recs[at + 33]]) as usize;
        clues.push(recs.get(at + 34..at + 34 + len).ok_or("a note's clue could not be derived — nothing was spent")?.to_vec());
        at += 34 + len;
    }
    if clues.len() != 2 {
        return Err("a note's clue could not be derived — nothing was spent".into());
    }
    let req = usdmd_node::pot_fill_tx::PotFillTx {
        burn_usdm: x,
        sat_out: s_out,
        nullifier: input_nf,
        leaf_commit: leaf4_to_bytes(leaf_commit),
        burn_carrier,
        membership_carrier: hex::decode(&mem_hex).map_err(|e| format!("member leg hex: {e}"))?,
        membership_tip: hex::decode(&tip_hex).map_err(|e| format!("member tip hex: {e}"))?,
        change_note: change_note.to_vec(),
        change_clue: clues[1].clone(),
        sat_note: sat_note.to_vec(),
        sat_mint_carrier: sat_carrier,
        sat_clue: clues[0].clone(),
        new_minted_commit: [0; usdm_decider::poseidon2_compress::DIGEST_LANES],
        retire_leg: Vec::new(),
        attestors: Vec::new(),
    };
    if !req.carriers_verify() {
        return Err("refusing: the buy does not verify against its own carriers — nothing was spent".into());
    }
    let reply: serde_json::Value = agent
        .post(&format!("{}/pot_buy", node_url()))
        .send_json(serde_json::json!({ "request_hex": hex::encode(req.encode()) }))
        .map_err(|e| format!("the node refused the buy: {}", node_refusal(e)))
        .and_then(|r| r.into_json().map_err(|e| format!("buy reply json: {e}")))?;
    if reply.get("relayed").and_then(|v| v.as_bool()) != Some(true) {
        return Err(reply.get("reason").and_then(|v| v.as_str()).unwrap_or("the node did not relay the buy").to_string());
    }
    reservation.commit(input_nf);
    Ok(serde_json::json!({ "relayed": true, "usdm": x as f64 / 1e8, "sat": s_out as f64 / 1e8 }))
}
off_ui_thread_approved!(wallet_pot_buy => wallet_pot_buy_blocking(usdm: f64) ; format!("Buy SAT from the repayment pot with {usdm} USDm at the floor price"));
