/// The approval line's words for a Buy SAT maximum-price bucket.
fn max_price_words(bucket: usize) -> String {
    match usdmd_node::defi_clear::BUCKET_TICKS.get(bucket).copied() {
        Some(Some(d)) => format!("fills only up to {:.0} % above the last price", (1.001f64.powi(d as i32) - 1.0) * 100.0),
        Some(None) => "no maximum price".to_string(),
        None => "an unknown maximum price".to_string(),
    }
}
