/// ⭐ DELEGATE — `amount_sat` of this wallet's SAT to validator `vid_hex` (empty: a seated validator picked at random from the
/// public list, so delegations spread across the set by default). One SAT note covers it; the change stays SAT.
fn wallet_delegate_sat_blocking(amount_sat: f64, vid_hex: String) -> Result<serde_json::Value, String> {
    use rand::RngCore as _;
    let amount = usdm_to_atomic(amount_sat)?;
    let v = delegation_view()?;
    let seated: Vec<[u8; 32]> = v.targets.iter().filter(|(_, s)| *s).map(|(id, _)| *id).collect();
    let vid = if vid_hex.trim().is_empty() {
        if seated.is_empty() {
            return Err("no validator holds a custody seat yet, so there is nothing to delegate to — nothing was spent".into());
        }
        seated[(rand::rngs::OsRng.next_u64() % seated.len() as u64) as usize]
    } else {
        let id = hex::decode(vid_hex.trim()).ok().and_then(|b| <[u8; 32]>::try_from(b.as_slice()).ok()).ok_or("that is not a validator id — nothing was spent")?;
        if !seated.contains(&id) {
            return Err("that validator holds no custody seat — nothing was spent".into());
        }
        id
    };
    let sat_tag = usdmd_node::satoshi::asset_tag();
    let input = {
        let held = PROVEN_SPENT.lock().unwrap_or_else(|e| e.into_inner()).clone();
        let s = SCAN.lock().unwrap_or_else(|e| e.into_inner());
        let st = s.as_ref().ok_or("no wallet open")?;
        st.owned
            .iter()
            .filter(|n| n.asset == sat_tag && n.amount >= amount && spendable_now(&st.spent, &st.pending_change, &held, n.amount, n.seed, &n.nf))
            .min_by_key(|n| n.amount)
            .map(|n| (n.amount, n.seed))
            .ok_or_else(|| format!("no single spendable SAT note covers {amount_sat} SAT — delegate up to your largest SAT note. Nothing was spent."))?
    };
    let mut r = sat_delegation_submit(usdmd_node::sat_delegation_tx::DelegationKind::Delegate { vid, y0: v.y }, amount, input, (0, 0))?;
    r["validator"] = serde_json::Value::String(hex::encode(vid));
    Ok(r)
}
off_ui_thread_approved!(wallet_delegate_sat => wallet_delegate_sat_blocking(amount_sat: f64, vid_hex: String) ; format!(
    "Delegate {amount_sat} SAT to a validator's custody bond. Network fee $0.00. It earns the bonders' share of every network \
     fee at that validator's uptime; undelegating takes 21 days. If it double-signs or deals a bad key only its own bond is burned \
     and your SAT comes back; if it helps steal from the reserve, SAT delegated to it is lost with it."
));

/// ⭐ UNDELEGATE — every delegated note this wallet holds, each into the unbonding colour maturing at the first epoch boundary
/// past the window (a short margin covers the block that carries it), paying the yield it earned since it last settled.
fn wallet_undelegate_sat_blocking() -> Result<serde_json::Value, String> {
    let v = delegation_view()?;
    let notes: Vec<_> = my_sat_colour_notes(&v).into_iter().filter(|n| matches!(n.2, SatColour::Delegated(..))).collect();
    if notes.is_empty() {
        return Err("you have no delegated SAT to undelegate".into());
    }
    let matures = usdmd_node::sat_delegation_tx::earliest_matures(v.tip_tick.saturating_add(UNDELEGATE_MARGIN_TICKS), v.window);
    let mut done = Vec::new();
    for (amount, seed, colour) in notes {
        let SatColour::Delegated(vid, y0) = colour else { continue };
        done.push(sat_delegation_submit(
            usdmd_node::sat_delegation_tx::DelegationKind::Undelegate { vid, y0, y_now: v.y, matures },
            amount,
            (amount, seed),
            v.uptime_of(&vid),
        )?);
    }
    Ok(serde_json::json!({ "undelegated": done, "matures_at_tick": matures, "tip_tick": v.tip_tick }))
}
/// The chain time between the tip a wallet reads and the block that carries its undelegation, in chain ticks (A-F60:
/// five minutes on the chain's clock, whatever the block rate): an over-estimate only delays maturity within the epoch
/// the rounding already adds.
const UNDELEGATE_MARGIN_TICKS: u64 = usdmd_node::params::blocks_for_ms(300_000);
off_ui_thread_approved!(wallet_undelegate_sat => wallet_undelegate_sat_blocking() ; "Undelegate all your delegated SAT. It \
    stops earning now, pays what it earned, and returns to your spendable SAT automatically after the 21-day unbonding \
    period. Network fee $0.00.".to_string());

/// ⭐ THE AUTOMATIC STEP — every matured unbonding note back into SAT, and every delegated note with yield to collect claimed
/// (§17.6). Run by hand and after each detection pass: the holder chose to delegate or undelegate; collecting what that choice
/// earns and returning matured SAT completes it, never a new one.
fn release_matured_sat() -> Result<serde_json::Value, String> {
    let v = delegation_view()?;
    let (mut released, mut claimed) = (Vec::new(), Vec::new());
    for (amount, seed, colour) in my_sat_colour_notes(&v) {
        match colour {
            SatColour::Unbonding(matures) if matures <= v.tip_tick => released.push(sat_delegation_submit(
                usdmd_node::sat_delegation_tx::DelegationKind::Release { matures },
                amount,
                (amount, seed),
                (0, 0),
            )?),
            SatColour::Delegated(vid, y0) if v.earned(amount, &vid, y0) > 0 => {
                let earned = v.earned(amount, &vid, y0);
                claimed.push(sat_delegation_submit(
                    usdmd_node::sat_delegation_tx::DelegationKind::Claim { vid, y0, y_now: v.y },
                    amount,
                    (amount, seed),
                    v.uptime_of(&vid),
                )?);
                note_reward_for_btc(u64::try_from(earned).unwrap_or(u64::MAX)); // §BR-8: "Take my rewards in Bitcoin"
            }
            _ => {}
        }
    }
    Ok(serde_json::json!({ "released": released, "claimed": claimed }))
}

/// ⭐ §BR-3 17.6 — CLAIM THIS WALLET'S VALIDATOR OWN-WEIGHT YIELD, if its seed-derived validator is owed any: the node serves
/// the amount owed at the chain's index (`/get_validator_bond`, public figures of a public seat); the wallet seals one USDm
/// note to itself at a reserved `chg` index, proves it with the mint carrier, signs the claim with its validator key and
/// posts it. Nothing moves locally: every node pays it from the bonders' pool when the block carrying it folds.
fn claim_own_bond_yield() -> Result<Option<serde_json::Value>, String> {
    let (validator_root, my_ek, loc_sk, keys) = {
        let g = WALLET.lock().unwrap_or_else(|e| e.into_inner());
        let w = g.as_ref().ok_or_else(|| "no wallet open".to_string())?;
        (w.validator_root, w.scan_ek.clone(), w.loc_sk, w.note_keys())
    };
    let ident = pq::derive_validator_identity(&validator_root, 0);
    let vid = usdmd_node::pqauth::pubkey_id(&ident.vote_pk);
    let agent = ureq::AgentBuilder::new().timeout(Duration::from_secs(10)).build();
    let r: serde_json::Value = agent
        .post(&format!("{}/get_validator_bond", node_url()))
        .send_json(serde_json::json!({ "voter_id": hex::encode(vid) }))
        .map_err(|e| format!("cannot read this validator's yield: {}", node_refusal(e)))?
        .into_json()
        .map_err(|e| format!("validator reply unreadable: {e}"))?;
    let owed = r.get("own_yield_atomic").and_then(|v| v.as_u64()).unwrap_or(0);
    let Some(y) = r.get("bond_yield_index").and_then(|v| v.as_str()).and_then(|s| s.parse::<u128>().ok()) else {
        return Ok(None);
    };
    if owed == 0 {
        return Ok(None);
    }
    let (note, opening) = pq::seal_note_full_asset(&my_ek, &keys.spk, owed, [0, 0, 0]).ok_or("could not seal the yield note")?;
    let (carrier, cm) =
        usdm_decider::whir_rec_block::prove_asset_mint_validity_bytes(owed, [0, 0, 0], &opening).ok_or("the yield note's carrier did not prove")?;
    let cmb = leaf4_to_bytes(cm);
    if note[..32] != cmb[..] {
        return Err("refusing: the yield note is not its carrier's".into());
    }
    let (owner_clue, reservation) = fresh_self_note_clue(&loc_sk, &note)?;
    let sig = usdmd_node::pqauth::ml_dsa_sign(
        &usdmd_node::bond_yield_claim_tx::claim_statement(&vid, y, owed, &cmb, &usdmd_node::oli::owner_clue_digest(&owner_clue)),
        &ident.vote_sk,
    )
    .ok_or("the validator key did not sign")?;
    let t = usdmd_node::bond_yield_claim_tx::BondYieldClaimTx {
        vid,
        y_now: y,
        amount: owed,
        note: note.to_vec(),
        carrier,
        owner_clue,
        pubkey: ident.vote_pk.clone(),
        sig,
    };
    let reply: serde_json::Value = agent
        .post(&format!("{}/submit_bond_yield_claim", node_url()))
        .send_json(serde_json::json!({ "object_hex": hex::encode(t.encode()) }))
        .map_err(|e| format!("the node refused the yield claim: {}", node_refusal(e)))
        .and_then(|r| r.into_json().map_err(|e| format!("claim reply json: {e}")))?;
    if reply.get("verdict").and_then(|v| v.as_str()) == Some("PUBLISHED") {
        reservation.commit(usdmd_node::bond_yield_claim_tx::claim_nf(&vid, y));
        note_reward_for_btc(owed); // §BR-8: "Take my rewards in Bitcoin"
    }
    Ok(Some(serde_json::json!({ "verdict": reply.get("verdict").cloned().unwrap_or("UNKNOWN".into()), "usdm": owed as f64 / 1e8 })))
}

static RELEASE_IN_FLIGHT: AtomicBool = AtomicBool::new(false);
/// ONE release-and-claim step after a detection pass. Non-fatal: a refusal is logged; the next pass tries again.
fn release_matured_step() {
    if RELEASE_IN_FLIGHT.swap(true, Ordering::SeqCst) {
        return;
    }
    if let Err(e) = release_matured_sat() {
        // DIGITAL-CASH-PRIVACY-REVIEWED: this wallet's own action on its own device's stderr, sent nowhere.
        eprintln!("[sat-release] not released or claimed this pass: {e}");
    }
    if let Err(e) = claim_own_bond_yield() {
        // DIGITAL-CASH-PRIVACY-REVIEWED: this wallet's own action on its own device's stderr, sent nowhere.
        eprintln!("[bond-yield] the validator's yield was not claimed this pass: {e}");
    }
    // §BR-8 B8-b: the remixer, when switched on, keeps its vault coins cycling through private rounds
    if mix_client::remix_on() {
        mix_client::remix_tick();
        let _ = mix_client::wallet_mix_progress_blocking();
    }
    RELEASE_IN_FLIGHT.store(false, Ordering::SeqCst);
}

/// This wallet's delegations as the SAT card shows them: delegated SAT per validator, and unbonding SAT per maturity.
fn wallet_delegations_blocking() -> Result<serde_json::Value, String> {
    let v = delegation_view()?;
    let rows: Vec<serde_json::Value> = my_sat_colour_notes(&v)
        .into_iter()
        .map(|(amount, _, c)| match c {
            SatColour::Delegated(id, y0) => serde_json::json!({
                "state": "delegated",
                "sat": amount as f64 / 1e8,
                "validator": hex::encode(id),
                "earned_usdm": usdmd_node::peg::bond_yield_between(u128::from(amount), y0, v.y) as f64 / 1e8,
            }),
            SatColour::Unbonding(m) => serde_json::json!({
                "state": if m <= v.tip_tick { "releasing" } else { "unbonding" },
                "sat": amount as f64 / 1e8,
                "matures_at_tick": m,
                // A-F60: ticks to days on the chain's clock (a tick is `MESH_TARGET_SPACING_MS` of median time past) —
                // never a block count over an assumed 172,800 blocks a day
                "days_left": (m.saturating_sub(v.tip_tick) * usdmd_node::dag::MESH_TARGET_SPACING_MS) as f64 / usdmd_node::params::DAY_MS as f64,
            }),
        })
        .collect();
    let seats = v.targets.iter().filter(|(_, s)| *s).count();
    // R7 F10: every validator a holder can delegate to, with its public custody weight (largest first)
    let mut validators: Vec<([u8; 32], u64)> = v.bonds.iter().map(|(id, b)| (*id, *b)).collect();
    validators.sort_by(|a, b| b.1.cmp(&a.1));
    let validators: Vec<serde_json::Value> =
        validators.iter().map(|(id, b)| serde_json::json!({ "validator": hex::encode(id), "sat": *b as f64 / 1e8 })).collect();
    Ok(serde_json::json!({ "delegations": rows, "validators_to_delegate_to": seats, "validators": validators }))
}
off_ui_thread!(wallet_delegations => wallet_delegations_blocking());

// ⭐⭐ §BR-12 — THE WALLET'S OWN INTERFACE FEES (spec §10): a front-end fee on the actions the wallet fronts, shown in dollars
// on the confirmation before the user acts, never holding, capping or refusing a movement. The fee is RECORDED as owed at the
// moment the action is accepted and PAID to the first-party publisher's address (`network_descriptor::
// canonical_publisher_address`) in one ordinary transfer once a week — the payment is byte-shape-identical to any other
// transfer, and batching hides which action earned it. The same action sent straight to a node pays only the protocol fee.
// cons: the publisher is paid up to one week late; a user may run another front end (every interface fee is optional by
// nature); the owed ledger is a local file (8 bytes + a timestamp).

/// The first-party rates (basis points of the action's dollar value), each beating the major rival (the ADOPTABLE table).
const FEE_BPS_SWAP: u64 = 25; // wallet swaps 0.25 % (MetaMask / Phantom ≈ 0.85 %)
const FEE_BPS_CASH: u64 = 10; // cash in / cash out 0.10 %
const FEE_BPS_POS: u64 = 50; // POS and tap-to-pay 0.5 %, paid by the merchant (card networks ≈ 2–3 %)
/// A username: about $10 a year, charged at registration.
const FEE_USERNAME_ATOMIC: u64 = 10 * 100_000_000;
/// The batched payout period: one week (user 2026-11-02). Each payout is one lump per device per week, so the publisher
/// never learns any single action's size or moment.
const INTERFACE_FEE_PERIOD_SECS: u64 = 7 * 24 * 3600;

/// The interface fee on an action worth `usdm_atomic` at `bps`: ⌊value · bps / 10 000⌋ (never more than shown).
fn interface_fee(usdm_atomic: u64, bps: u64) -> u64 {
    (u128::from(usdm_atomic) * u128::from(bps) / 10_000) as u64
}

fn interface_fee_path() -> std::path::PathBuf {
    node_data_dir().join("interface-fees.json")
}
/// `(owed atomic, unix seconds of the last payout or of the first fee owed)`.
fn interface_fee_ledger() -> (u64, u64) {
    interface_fee_ledger_at(&interface_fee_path())
}
fn interface_fee_ledger_at(path: &std::path::Path) -> (u64, u64) {
    std::fs::read_to_string(path)
        .ok()
        .and_then(|s| serde_json::from_str::<serde_json::Value>(&s).ok())
        .map(|v| (v["owed"].as_u64().unwrap_or(0), v["since"].as_u64().unwrap_or(0)))
        .unwrap_or((0, 0))
}
fn write_interface_fee_ledger(owed: u64, since: u64) {
    write_interface_fee_ledger_at(&interface_fee_path(), owed, since);
}
fn write_interface_fee_ledger_at(path: &std::path::Path, owed: u64, since: u64) {
    if let Some(dir) = path.parent() {
        let _ = std::fs::create_dir_all(dir);
    }
    let _ = std::fs::write(path, serde_json::json!({ "owed": owed, "since": since }).to_string());
}
/// Record `fee` as owed in the ledger at `path` at time `now` (the first fee starts the period's clock).
fn owe_interface_fee_at(path: &std::path::Path, fee: u64, now: u64) -> u64 {
    if fee == 0 {
        return 0;
    }
    let (owed, since) = interface_fee_ledger_at(path);
    write_interface_fee_ledger_at(path, owed.saturating_add(fee), if since == 0 { now } else { since });
    fee
}
/// Is a payout due at `now` for a ledger `(owed, since)`? Only a non-zero debt a whole period old.
fn interface_fee_due(owed: u64, since: u64, now: u64) -> bool {
    owed > 0 && now.saturating_sub(since) >= INTERFACE_FEE_PERIOD_SECS
}
fn unix_now_secs() -> u64 {
    std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.as_secs())
}
/// Record `fee` atomic USDm as owed (the action it was shown on was accepted). Returns the fee recorded.
fn owe_interface_fee(fee: u64) -> u64 {
    owe_interface_fee_at(&interface_fee_path(), fee, unix_now_secs())
}
static INTERFACE_FEE_IN_FLIGHT: AtomicBool = AtomicBool::new(false);
/// ONE payout step after a detection pass: once a week has passed since the last payout and a publisher address is
/// compiled in, the owed total goes out in one ordinary transfer; the ledger is zeroed only when the transfer is accepted.
/// Never blocks anything: a refusal (no balance yet, no publisher) is retried next pass.
fn interface_fee_step() -> Option<serde_json::Value> {
    let (owed, since) = interface_fee_ledger();
    if !interface_fee_due(owed, since, unix_now_secs()) {
        return None;
    }
    let to = crate::network_descriptor::canonical_publisher_address()?;
    if INTERFACE_FEE_IN_FLIGHT.swap(true, Ordering::SeqCst) {
        return None;
    }
    let r = wallet_send_blocking(to, owed as f64 / 1e8);
    if r.as_ref().is_ok_and(|v| v.get("ok").and_then(|x| x.as_bool()) != Some(false)) {
        write_interface_fee_ledger(0, unix_now_secs());
    }
    INTERFACE_FEE_IN_FLIGHT.store(false, Ordering::SeqCst);
    Some(r.unwrap_or_else(|e| serde_json::json!({ "error": e })))
}
/// ⭐ SUPPORT THE TEAM (user 2026-11-02): an OPT-IN fee of 0.10 % of each send the user makes, OFF by default. The switch is
/// persisted per device beside the note store (absent = OFF) and stays as the user last set it. The fee is never a second
/// output on the send: it joins the interface-fee ledger and leaves in the same weekly batched transfer, so a send with the
/// switch on is byte-shape-identical to one with it off, and nothing on chain says who opted in.
/// cons: none on chain; locally one 3-byte file.
/// LOCAL-STORAGE-REQUIRED: the user's own private preference; on chain it would reveal who opted in, and no proof or DA
/// record holds a per-device UI choice.
/// bound: one file of at most 3 bytes per device, never a term in height, blocks or notes.
const FEE_BPS_SUPPORT: u64 = 10;
fn support_fee_path() -> std::path::PathBuf {
    node_data_dir().join("support-fee")
}
fn support_fee_on_at(path: &std::path::Path) -> bool {
    std::fs::read_to_string(path).is_ok_and(|s| s.trim() == "on") // O1-INFINITY-REVIEWED: a fixed 3-byte UI preference, not chain authority; constant at any height
}
fn set_support_fee_at(path: &std::path::Path, on: bool) -> Result<(), String> {
    if let Some(dir) = path.parent() {
        let _ = std::fs::create_dir_all(dir);
    }
    std::fs::write(path, if on { "on" } else { "off" }).map_err(|e| format!("could not save the setting: {e}"))
}
/// The support fee on a send of `usdm_atomic`, recorded as owed in the ledger at `ledger` only when the switch at `switch`
/// is on and the send was accepted. Returns the fee recorded (0 when off or refused).
fn owe_support_fee_at(switch: &std::path::Path, ledger: &std::path::Path, usdm_atomic: u64, accepted: bool, now: u64) -> u64 {
    if !accepted || !support_fee_on_at(switch) {
        return 0;
    }
    owe_interface_fee_at(ledger, interface_fee(usdm_atomic, FEE_BPS_SUPPORT), now)
}
/// A send the USER makes (the Send button, a dApp transfer the user approved): the ordinary send, then the support fee if
/// opted in. The weekly payout calls `wallet_send_blocking` directly, so it never charges a fee on itself.
fn wallet_user_send_blocking(to: String, amount_usdm: f64) -> Result<serde_json::Value, String> {
    let r = wallet_send_blocking(to, amount_usdm);
    let accepted = r.as_ref().is_ok_and(|v| v.get("ok").and_then(|x| x.as_bool()) != Some(false));
    if let Ok(atomic) = usdm_to_atomic(amount_usdm) {
        owe_support_fee_at(&support_fee_path(), &interface_fee_path(), atomic, accepted, unix_now_secs());
    }
    r
}
#[tauri::command]
fn wallet_support_fee() -> Result<serde_json::Value, String> {
    Ok(serde_json::json!({ "on": support_fee_on_at(&support_fee_path()), "bps": FEE_BPS_SUPPORT }))
}
fn wallet_set_support_fee_blocking(on: bool) -> Result<serde_json::Value, String> {
    set_support_fee_at(&support_fee_path(), on)?;
    wallet_support_fee()
}
off_ui_thread!(wallet_set_support_fee => wallet_set_support_fee_blocking(on: bool));

/// §BR-12 — the cash-in fee (0.10 % of the USDm the deposit mints), owed once: only on the swap's first move to minted.
fn owe_cash_in_fee(rec: &SwapRec) {
    if rec.status != "minted" && rec.status != "redeemed" {
        if let Ok(atomic) = usdm_to_atomic(rec.usdm_out) {
            owe_interface_fee(interface_fee(atomic, FEE_BPS_CASH));
        }
    }
}
/// The rates and what is owed, for the confirmation lines and Settings.
fn wallet_interface_fees() -> Result<serde_json::Value, String> {
    let (owed, since) = interface_fee_ledger();
    Ok(serde_json::json!({
        "swap_bps": FEE_BPS_SWAP,
        "cash_bps": FEE_BPS_CASH,
        "pos_bps": FEE_BPS_POS,
        "username_usdm": FEE_USERNAME_ATOMIC as f64 / 1e8,
        "owed_usdm": owed as f64 / 1e8,
        "owed_since": since,
        "publisher": crate::network_descriptor::canonical_publisher_address().is_some(),
    }))
}
off_ui_thread!(wallet_interface_fees_cmd => wallet_interface_fees());

#[cfg(test)]
mod interface_fee_pins {
    use super::*;

    /// ⭐ A COIN SWAP REFUSES BEFORE ANYTHING IS QUOTED OR SENT: only Bitcoin ↔ Monero, a Monero payout needs a Monero
    /// address, a Bitcoin payout an empty field (the vault) or a Bitcoin address — every refusal names what to fix, and none
    /// reaches the node or writes a swap record. The second leg's state round-trips through the swap record (old records
    /// without it read as a plain buy).
    /// TWO-PARTY-REVIEWED: this pins the wallet's own input refusals, which run before any node is reached; the two-sided legs
    /// (the mint on one ledger, the cash-out from the other) are the node's peg pins (`the_monero_ledger_mints_and_redeems_…`).
    #[test]
    /// TWO-PARTY-REVIEWED: a pure function of ONE wallet's own draws (no value moves, no peer is judged); the cross-node claim
    /// — a leg at an epoch anchor admitted on a peer, the batch gate at every attestor — is the node's `br9a_c4_*` pins.
    /// ⭐ §19.4 — EACH CLAIM RELAYS AT ITS OWN DRAWN MOMENT, inside [now, ten minutes before its batch): custody cannot group
    /// one cash-out's pieces by arrival. Calibration: two draws differ (the window is wide), a piece whose batch is under ten
    /// minutes away relays at once, and the fast switch (pay-after 0) relays at once. And the cash-out ladder splits exactly,
    /// largest rung first, the remainder below $10 staying USDm.
    fn br9a_c4_each_claim_relays_at_its_own_moment_before_its_batch() {
        let now = || std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).unwrap().as_millis() as u64;
        let e = usdmd_node::epoch_deal_tx::EPOCH_MS;
        let tip = 10 * e + 5_000; // the chain clock now
        let pay_after = 12 * e + 100_000; // batch at the start of epoch 13
        let batch_ms = 13 * e - tip;
        let mut rng = rand::rngs::OsRng;
        let draws: Vec<u64> = (0..64).map(|_| claim_relay_moment_ms(pay_after, tip, &mut rng)).collect();
        let t1 = now();
        for d in &draws {
            assert!(*d + 1_000 >= t1 && *d <= t1 + batch_ms - 600_000 + 1_000, "⛔ a claim relays outside its window");
        }
        assert!(draws.iter().any(|d| *d != draws[0]), "⛔ every piece relayed at one moment (custody groups them)");
        assert!(claim_relay_moment_ms(0, tip, &mut rng) <= now() + 1_000, "the fast switch relays at once");
        assert!(claim_relay_moment_ms(13 * e - 1, 13 * e - 600_000, &mut rng) <= now() + 1_000, "a batch under ten minutes away relays at once");
        let (rungs, rest) = usdmd_node::peg_pool::split_to_usd_denoms(1_234_56_000_000);
        assert_eq!(rungs.iter().sum::<u64>() + rest, 1_234_56_000_000);
        assert!(rungs.iter().all(|r| usdmd_node::peg_pool::is_usd_denom(*r)) && rest < usdmd_node::peg_pool::USD_DENOMS[0]);
        assert_eq!(rungs.len(), 1 + 2 + 3, "$1,234.56 = 1 × $1,000 + 2 × $100 + 3 × $10, $4.56 stays USDm");
    }

    #[test]
    fn a_coin_swap_refuses_a_wrong_pair_or_payout_before_anything_is_sent() {
        for (from, to) in [("BTC", "BTC"), ("XMR", "XMR"), ("USDM", "BTC"), ("BTC", "SAT")] {
            let e = wallet_coin_swap_blocking(from.into(), to.into(), 10.0, String::new()).expect_err("a wrong pair is refused");
            assert!(e.contains("Bitcoin → Monero"), "{from}→{to}: {e}");
        }
        let e = wallet_coin_swap_blocking("BTC".into(), "XMR".into(), 10.0, "bc1qnotmonero".into()).expect_err("a Monero payout needs a Monero address");
        assert!(e.contains("Monero address"), "{e}");
        let e = wallet_coin_swap_blocking("XMR".into(), "BTC".into(), 10.0, "not-an-address".into()).expect_err("a bad Bitcoin payout is refused");
        assert!(e.contains("not a Bitcoin address"), "{e}");
        let tp = ThenPay { asset: "XMR".into(), payout_to: "4abc".into(), status: "pending".into(), cash_out: None };
        let back: ThenPay = serde_json::from_value(serde_json::to_value(&tp).unwrap()).unwrap();
        assert_eq!((back.asset.as_str(), back.status.as_str()), ("XMR", "pending"));
        let legacy: Option<ThenPay> = serde_json::from_value(serde_json::Value::Null).unwrap();
        assert!(legacy.is_none(), "a record from before coin swaps reads as a plain buy");
    }

    /// ⭐ §BR-12 — THE WALLET'S FEE IS NEVER MORE THAN THE CONFIRMATION SHOWED, AND IS RECORDED EXACTLY ONCE. The swap
    /// confirmation shows 0.25 % of the most the swap can pay; the fee recorded is 0.25 % of what the settled rungs moved
    /// (never above it). Cash 0.10 %, POS 0.5 %, floored. The ledger adds exactly each fee, the first fee starts the period,
    /// a payout is due only for a non-zero debt a whole period (one week) old, and a zero fee records nothing. A swap sent straight to a
    /// node never touches this ledger (the fee lives only in the wallet's own door).
    #[test]
    fn the_wallet_fee_never_exceeds_what_was_shown_and_is_owed_exactly_once_then_paid_weekly() {
        let budget = 400_000_000u64; // $4 at most
        let shown = interface_fee(budget, FEE_BPS_SWAP);
        assert_eq!(shown, 1_000_000, "0.25 % of $4 is $0.01");
        for settled in [0, 1, 123_456_789, budget] {
            assert!(interface_fee(settled, FEE_BPS_SWAP) <= shown, "⛔ the recorded fee exceeded the shown one at {settled}");
        }
        assert_eq!(interface_fee(1_000 * 100_000_000, FEE_BPS_CASH), 100_000_000, "0.10 % of $1,000 is $1");
        assert_eq!(interface_fee(100 * 100_000_000, FEE_BPS_POS), 50_000_000, "0.5 % of $100 is $0.50");
        assert_eq!(interface_fee(399, FEE_BPS_SWAP), 0, "floored: never rounds up");
        let dir = std::env::temp_dir().join(format!("musd-ifee-{}", std::process::id()));
        let path = dir.join("interface-fees.json");
        let _ = std::fs::remove_file(&path);
        assert_eq!(owe_interface_fee_at(&path, 0, 10), 0);
        assert_eq!(interface_fee_ledger_at(&path), (0, 0), "a zero fee records nothing");
        owe_interface_fee_at(&path, shown, 1_000);
        owe_interface_fee_at(&path, 7, 2_000);
        assert_eq!(interface_fee_ledger_at(&path), (shown + 7, 1_000), "exactly the fees, the clock from the first");
        assert!(!interface_fee_due(shown + 7, 1_000, 1_000 + INTERFACE_FEE_PERIOD_SECS - 1), "not before a week");
        assert!(interface_fee_due(shown + 7, 1_000, 1_000 + INTERFACE_FEE_PERIOD_SECS), "due after a week");
        assert_eq!(INTERFACE_FEE_PERIOD_SECS, 604_800, "the batched payout period is one week");
        assert!(!interface_fee_due(0, 0, u64::MAX), "nothing owed, nothing paid");
        let _ = std::fs::remove_dir_all(&dir);
    }

    /// ⭐ SUPPORT THE TEAM — OFF UNTIL THE USER TURNS IT ON, AND IT STAYS WHERE THEY LEFT IT. A fresh device owes nothing on
    /// a send; once on, every accepted send owes exactly 0.10 % (floored) and a refused send owes nothing; turned off, the
    /// next send owes nothing again; each state survives a re-read (a restart reads the same file). Tamper: a corrupt switch
    /// file reads OFF, never on. The weekly payout never charges itself (it calls the plain send, not the user send).
    /// TWO-PARTY-REVIEWED: one device's own preference and its own owed ledger — no value moves and no peer judges it; the
    /// payout that crosses the boundary is the ordinary send, pinned by the cross-node send pins.
    /// LOCAL-STORAGE-REQUIRED: the tamper step corrupts the switch file in a per-test temp dir, removed at the end.
    /// bound: one 7-byte temp file, deleted by the test.
    #[test]
    fn the_support_fee_is_off_by_default_persists_and_is_owed_only_on_an_accepted_send() {
        let dir = std::env::temp_dir().join(format!("musd-support-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        let (sw, led) = (dir.join("support-fee"), dir.join("interface-fees.json"));
        let send = 100 * 100_000_000u64; // $100
        assert!(!support_fee_on_at(&sw), "⛔ a fresh device must start with the support fee OFF");
        assert_eq!(owe_support_fee_at(&sw, &led, send, true, 1), 0, "⛔ a fee was owed with the switch never turned on");
        set_support_fee_at(&sw, true).unwrap();
        assert!(support_fee_on_at(&sw), "on, and it reads back on (a restart reads the same)");
        assert_eq!(owe_support_fee_at(&sw, &led, send, true, 5), 10_000_000, "0.10 % of $100 is $0.10");
        assert_eq!(owe_support_fee_at(&sw, &led, send, false, 6), 0, "⛔ a refused send was charged");
        assert_eq!(owe_support_fee_at(&sw, &led, 999, true, 7), 0, "floored: never rounds up");
        assert_eq!(interface_fee_ledger_at(&led), (10_000_000, 5), "exactly one fee owed, the period's clock from it");
        set_support_fee_at(&sw, false).unwrap();
        assert!(!support_fee_on_at(&sw), "off, and it reads back off");
        assert_eq!(owe_support_fee_at(&sw, &led, send, true, 8), 0, "⛔ a fee was owed after the user turned it off");
        std::fs::write(&sw, "garbage").unwrap();
        assert!(!support_fee_on_at(&sw), "⛔ a corrupt switch file read as ON");
        let prod = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/src/lib.rs")).unwrap();
        let step = &prod[prod.find("fn interface_fee_step(").unwrap()..];
        let step = &step[..step.find("\n}\n").unwrap()];
        assert!(!step.contains("wallet_user_send_blocking("), "⛔ the weekly payout would charge a support fee on itself");
        let _ = std::fs::remove_dir_all(&dir);
    }
}

/// ⭐ §BR-10 — WHAT THE UPDATES CARD SHOWS: the releases ≥ 3 builders attest on chain (the node's `/release_attestations`)
/// that are newer than this build, and the network's deployment states (`/get_rule_set`). Nothing is downloaded or installed.
fn wallet_update_status_blocking() -> Result<serde_json::Value, String> {
    let agent = ureq::AgentBuilder::new().timeout(Duration::from_secs(8)).build();
    let get = |path: &str| -> Option<serde_json::Value> {
        agent.get(&format!("{}{path}", node_url())).call().ok().and_then(|r| r.into_json().ok())
    };
    let current = env!("CARGO_PKG_VERSION");
    let newer = |v: &str| -> bool {
        let parse = |s: &str| s.split('.').map(|x| x.parse::<u64>().unwrap_or(0)).collect::<Vec<u64>>();
        parse(v) > parse(current)
    };
    let offered = get("/release_attestations")
        .and_then(|j| j.get("releases").and_then(|v| v.as_array()).cloned())
        .unwrap_or_default();
    let best = offered.iter().find(|r| r.get("version").and_then(|v| v.as_str()).is_some_and(newer));
    let rule_set = get("/get_rule_set");
    let deployments = rule_set.as_ref().and_then(|j| j.get("deployments").cloned()).unwrap_or(serde_json::json!([]));
    // spec §8: a node that falls behind an activation keeps following the one DAG in safe mode, and the wallet says so
    let update_needed = rule_set.as_ref().and_then(|j| j.get("update_needed").and_then(|v| v.as_bool())).unwrap_or(false);
    Ok(match best {
        Some(r) => serde_json::json!({
            "available": true,
            "current": current,
            "version": r.get("version").cloned().unwrap_or_default(),
            "notes": r.get("notes").cloned().unwrap_or_default(),
            "emergency": r.get("emergency").cloned().unwrap_or(false.into()),
            "builders": r.get("builders").cloned().unwrap_or(0.into()),
            "release_hash": r.get("release_hash").cloned().unwrap_or_default(),
            "deployments": deployments,
            "update_needed": update_needed,
        }),
        None => serde_json::json!({ "available": false, "current": current, "deployments": deployments, "update_needed": update_needed }),
    })
}
off_ui_thread!(wallet_update_status => wallet_update_status_blocking());

/// ⭐ §BR-10 — CHECK A DOWNLOADED RELEASE: its release root (`usdmd_node::release::release_root`, the content address builders
/// attest) against every release ≥ 3 builders attest. Reads the file locally; sends nothing anywhere.
fn wallet_verify_release_blocking(path: String) -> Result<serde_json::Value, String> {
    let bytes = std::fs::read(path.trim()).map_err(|e| format!("cannot read that file: {e}"))?;
    let h = usdmd_node::release::release_root(&bytes).map(hex::encode).ok_or("that file is no release (empty, or past 1 GiB)")?;
    let offered: Vec<String> = ureq::AgentBuilder::new()
        .timeout(Duration::from_secs(8))
        .build()
        .get(&format!("{}/release_attestations", node_url()))
        .call()
        .ok()
        .and_then(|r| r.into_json::<serde_json::Value>().ok())
        .and_then(|j| j.get("releases").and_then(|v| v.as_array()).cloned())
        .unwrap_or_default()
        .iter()
        .filter_map(|r| r.get("release_hash").and_then(|v| v.as_str()).map(str::to_string))
        .collect();
    Ok(serde_json::json!({ "matches": offered.contains(&h), "hash": h }))
}
off_ui_thread!(wallet_verify_release => wallet_verify_release_blocking(path: String));

/// ⭐⭐ §BR-10 — DOWNLOAD THE ATTESTED RELEASE, ONE STEP PER CALL (the Updates card calls it while it shows progress). This
/// wallet's own node asks its peers for every chunk it lacks over the bulk lane, each checked against the root three builders
/// attest before it is stored; when all are held, the wallet reads them over loopback, re-checks the WHOLE file against that
/// root, and writes it to Downloads. It never installs anything: the user taps "Open installer" (the Bitcoin model).
fn wallet_download_release_blocking() -> Result<serde_json::Value, String> {
    let agent = ureq::AgentBuilder::new().timeout(Duration::from_secs(30)).build();
    let post = |path: &str, body: serde_json::Value| -> Result<serde_json::Value, String> {
        agent
            .post(&format!("{}{path}", node_url()))
            .send_json(body)
            .map_err(|e| format!("the node did not answer: {}", node_refusal(e)))?
            .into_json()
            .map_err(|e| format!("the node's answer: {e}"))
    };
    let st = post("/release_fetch", serde_json::json!({}))?;
    let root = st.get("root").and_then(|v| v.as_str()).ok_or("no release three builders attest is offered on the chain")?.to_string();
    let held = st.get("held").and_then(|v| v.as_u64()).unwrap_or(0);
    let Some(n) = st.get("chunks").and_then(|v| v.as_u64()) else {
        return Ok(serde_json::json!({ "done": false, "held": held, "chunks": null, "root": root }));
    };
    if held < n {
        return Ok(serde_json::json!({ "done": false, "held": held, "chunks": n, "root": root }));
    }
    let mut file = Vec::new();
    for i in 0..n {
        let r = post("/release_chunk", serde_json::json!({ "index": i }))?;
        let c = r
            .get("chunk_hex")
            .and_then(|v| v.as_str())
            .and_then(|h| hex::decode(h).ok())
            .ok_or("a chunk the node said it held did not arrive — try again")?;
        file.extend_from_slice(&c);
    }
    let got = usdmd_node::release::release_root(&file).map(hex::encode);
    if got.as_deref() != Some(root.as_str()) {
        return Err("the downloaded release does NOT match what the builders attested — nothing was saved".into());
    }
    let version = wallet_update_status_blocking().ok().and_then(|s| s.get("version").and_then(|v| v.as_str()).map(str::to_string)).unwrap_or_default();
    let name = format!("MonerousD-{}{}", if version.is_empty() { root[..12].to_string() } else { version }, if cfg!(target_os = "macos") { ".dmg" } else { ".bin" });
    let dir = dirs_downloads().unwrap_or_else(std::env::temp_dir);
    let path = dir.join(name);
    std::fs::write(&path, &file).map_err(|e| format!("could not save the release: {e}"))?;
    Ok(serde_json::json!({ "done": true, "held": n, "chunks": n, "root": root, "path": path.to_string_lossy() }))
}
off_ui_thread!(wallet_download_release => wallet_download_release_blocking());

/// The user's Downloads folder (`$HOME/Downloads`).
fn dirs_downloads() -> Option<std::path::PathBuf> {
    std::env::var_os("HOME").map(|h| std::path::PathBuf::from(h).join("Downloads")).filter(|d| d.is_dir())
}

/// ⭐ §BR-10 — OPEN THE CHECKED INSTALLER, only on the user's tap, and only a file whose release root three builders attest.
fn wallet_open_release_blocking(path: String) -> Result<serde_json::Value, String> {
    let v = wallet_verify_release_blocking(path.clone())?;
    if v.get("matches").and_then(|m| m.as_bool()) != Some(true) {
        return Err("this file is NOT the attested release — it was not opened".into());
    }
    #[cfg(target_os = "macos")]
    let opener = "open";
    #[cfg(not(target_os = "macos"))]
    let opener = "xdg-open";
    std::process::Command::new(opener).arg(path.trim()).spawn().map_err(|e| format!("could not open the installer: {e}"))?;
    Ok(serde_json::json!({ "opened": true }))
}
off_ui_thread!(wallet_open_release => wallet_open_release_blocking(path: String));

const AUTO_OPSEC_REFUSES_FAST: &str = "Auto-OPSEC is on, so each piece pays in a random batch among many same-size payouts. \
     To pay now (not private), turn Auto-OPSEC off.";

/// ⭐ §BR-2 — the deposit key at `index`: `blake3_derive("MUSD/btc-depositor/v1", phrase ‖ index)`, restore-able from the 24
/// words; returns (secret, x-only key). The curve work is the node's Bitcoin endpoint (`btc_tx`, CLASSICAL-CRYPTO-EXEMPT:
/// Bitcoin admits only its own curve).
fn depositor_key_at(index: u32) -> Result<([u8; 32], [u8; 32]), String> {
    let phrase = std::fs::read_to_string(node_data_dir().join("seed"))
        .ok()
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .ok_or("a Bitcoin deposit needs this device's persisted 24 words — restore once more to persist them")?;
    let mut h = blake3::Hasher::new_derive_key("MUSD/btc-depositor/v1");
    h.update(phrase.as_bytes());
    h.update(&index.to_le_bytes());
    let secret: [u8; 32] = *h.finalize().as_bytes();
    let x = usdmd_node::btc_tx::xonly_pubkey(&secret).ok_or("depositor key derivation refused")?;
    Ok((secret, x))
}

fn next_depositor_index(swaps: &[SwapRec]) -> u32 {
    swaps.iter().filter_map(|s| s.depositor_index).max().map_or(0, |i| i + 1)
}

/// The sweep's fee this wallet signs: twice the floor, so it relays through ordinary fee pressure (custody can bump it by
/// CPFP alone if a spike strands it).
const SWEEP_FEE_SATS: u64 = 2 * usdmd_node::btc_tx::DEPOSIT_SWEEP_FEE_MIN_SATS;

/// §BR-2 / DB-124 — the sats a Bitcoin deposit must carry to mint `usdm` at `backing_bps`, priced at the chain's mark
/// (inverse of the cash-out's `release = burn × scale / price`), plus the sweep's fee. `None` without a mark.
fn deposit_atomic_for(asset: &str, usdm: f64, backing_bps: u64) -> Option<u64> {
    // the deposit is valued on its OWN ledger at its OWN mark: sats at the BTC mark (plus the custody sweep's fee), piconero
    // at the XMR mark (Monero's ledger, `peg::XMR_PEG_ASSET_ID`; the sender pays Monero's network fee on top)
    if asset != "BTC" && asset != "XMR" {
        return None;
    }
    let (price, scale, _) = price_mark_for(asset).ok()?;
    let usdm_atomic = u128::from(usdm_to_atomic(usdm).ok()?);
    let backed = usdm_atomic.checked_mul(u128::from(backing_bps))? / 10_000;
    let units = u64::try_from((backed.checked_mul(scale)?).div_ceil(price.max(1))).ok()?;
    if asset == "XMR" {
        return Some(units);
    }
    units.checked_add(SWEEP_FEE_SATS)
}

/// The custody leaf behind this wallet's deposit address, asked of its node and CHECKED: the two-leaf output it derives
/// for (D, blind) must be the very address this wallet deposited to — a node that lied would derive another address.
fn verified_deposit_leaf(
    reserve_address: &str,
    d_blind: &Digest4,
    d_x: &[u8; 32],
) -> Result<(usdmd_node::btc_tx::CustodyLeaf, usdmd_node::btc_tx::DepositOutput), String> {
    let agent = ureq::AgentBuilder::new().timeout(Duration::from_secs(10)).build();
    let nonce = usdmd_node::spend_frontier::digest_to_lane_bytes(d_blind);
    let v: serde_json::Value = agent
        .post(&format!("{}/btc_deposit_leaf", node_url()))
        .send_json(serde_json::json!({ "address": reserve_address, "d_blind_hex": hex::encode(nonce), "depositor_x_hex": hex::encode(d_x) }))
        .map_err(|e| format!("deposit leaf: {}", node_refusal(e)))?
        .into_json()
        .map_err(|e| format!("deposit leaf json: {e}"))?;
    let k = v["k"].as_u64().ok_or("the node knows no custody leaf for this deposit")? as u32;
    let slots: Vec<[u8; 32]> = v["slot_keys_hex"]
        .as_array()
        .ok_or("the node knows no custody leaf for this deposit")?
        .iter()
        .filter_map(|x| hex::decode(x.as_str()?).ok()?.try_into().ok())
        .collect();
    let leaf = usdmd_node::btc_tx::custody_leaf_with_slots(&slots, k).ok_or("the node's custody leaf does not build")?;
    let out = usdmd_node::btc_tx::deposit_output(&leaf, d_x, &nonce).ok_or("the deposit output does not build")?;
    if usdmd_node::btc_tx::reserve_address(usdmd_node::bridge::btc_hrp(), &out.output_x) != reserve_address {
        return Err("⛔ the node's custody leaf does not derive this wallet's deposit address — refusing to sign".into());
    }
    Ok((leaf, out))
}

/// The deposit coin at `reserve_address` as this wallet's node's watcher holds it: the largest one (txid display, vout,
/// value, confirmations, funding scripts).
fn deposit_coin_at(reserve_address: &str) -> Result<serde_json::Value, String> {
    let agent = ureq::AgentBuilder::new().timeout(Duration::from_secs(10)).build();
    let v: serde_json::Value = agent
        .post(&format!("{}/btc_deposit_coin", node_url()))
        .send_json(serde_json::json!({ "address": reserve_address }))
        .map_err(|e| format!("deposit coin: {}", node_refusal(e)))?
        .into_json()
        .map_err(|e| format!("deposit coin json: {e}"))?;
    v["coins"]
        .as_array()
        .and_then(|c| c.iter().max_by_key(|x| x["value_sats"].as_u64().unwrap_or(0)).cloned())
        .ok_or_else(|| "the node does not see the deposit coin yet".to_string())
}

/// ⭐ §BR-2 — sign the custody's SWEEP of this swap's deposit coin (the request fields the node seals to every custodian).
/// Records the coin's senders (a cash-out to one of them is refused).
fn deposit_sweep_authorization(swap: &mut SwapRec, reserve_address: &str, d_blind: &Digest4) -> Result<serde_json::Value, String> {
    let index = swap.depositor_index.ok_or("this deposit has no depositor key (a pre-§BR-2 swap) — it cannot be co-signed")?;
    let (d_sk, d_x) = depositor_key_at(index)?;
    let (leaf, out) = verified_deposit_leaf(reserve_address, d_blind, &d_x)?;
    let coin = deposit_coin_at(reserve_address)?;
    if let Some(f) = coin["funding_scripts_hex"].as_array() {
        swap.funding_scripts_hex = f.iter().filter_map(|x| x.as_str().map(str::to_string)).collect();
    }
    let txid_display = coin["txid"].as_str().ok_or("deposit coin txid")?.to_string();
    let txid = usdmd_node::btc_tx::txid_from_display_hex(&txid_display).ok_or("deposit coin txid")?;
    let vout = coin["vout"].as_u64().ok_or("deposit coin vout")? as u32;
    let value = coin["value_sats"].as_u64().ok_or("deposit coin value")?;
    let nonce = usdmd_node::spend_frontier::digest_to_lane_bytes(d_blind);
    let (tx, _) = usdmd_node::btc_tx::deposit_sweep_payout(&out, &leaf, &nonce, txid, vout, value, SWEEP_FEE_SATS)
        .ok_or("the deposit is too small to sweep (its fee would leave dust)")?;
    let m = usdmd_node::btc_tx::deposit_sweep_sighash(&tx, &out).ok_or("the sweep's sighash")?;
    let mut aux = [0u8; 32];
    rand::RngCore::fill_bytes(&mut rand::rngs::OsRng, &mut aux);
    let sig = usdmd_node::btc_tx::sign_sighash(&d_sk, &m, &aux).ok_or("the sweep signature")?; // CLASSICAL-CRYPTO-EXEMPT: the depositor's BIP-340 signature on Bitcoin (bridge endpoint)
    Ok(serde_json::json!({
        "depositor_x_hex": hex::encode(d_x),
        "sweep_txid": txid_display,
        "sweep_vout": vout,
        "sweep_value_sats": value,
        "sweep_fee_sats": SWEEP_FEE_SATS,
        "sweep_sig_hex": hex::encode(sig),
    }))
}

/// §BR-1/§BR-2 — a cash-out to an address that SENT one of this wallet's deposits links the exit to that entry (the
/// attacker's address-reuse heuristic): refused, by name.
fn refuse_deposit_sender(address: &str) -> Result<(), String> {
    let swaps = read_swaps();
    deposit_sender_refusal(address, swaps.iter().flat_map(|s| s.funding_scripts_hex.iter()), auto_opsec_on())
}

/// The rule [`refuse_deposit_sender`] applies, over the scripts this wallet's deposits were funded from (pinned in
/// `a4_protection_tests`): while Auto-OPSEC is on, an address whose script funded a deposit is refused by name.
fn deposit_sender_refusal<'a>(address: &str, funding: impl IntoIterator<Item = &'a String>, opsec_on: bool) -> Result<(), String> {
    if !opsec_on {
        return Ok(()); // the user turned Auto-OPSEC off through its warning: any address
    }
    let Some((_, spk)) = usdmd_node::btc_tx::script_pubkey_for_address(address) else { return Ok(()) };
    let spk_hex = hex::encode(spk);
    if funding.into_iter().any(|f| *f == spk_hex) {
        return Err("this address sent one of your deposits — paying it back would link this cash-out to that deposit. \
                    Cash out to your vault (a fresh address for every piece) or to an address that never paid you in."
            .into());
    }
    Ok(())
}

/// ⭐ §BR-2 — what a reclaim of this swap's deposit would return, before the user confirms it: the coin, the refund fee,
/// what lands in the vault, and how many Bitcoin blocks remain until the refund leaf opens (0 = it is open now).
fn wallet_reclaim_deposit_quote_blocking(swap_id: String) -> Result<serde_json::Value, String> {
    let list = read_swaps();
    let s = list.iter().find(|s| s.swap_id == swap_id).ok_or("swap not found")?;
    if s.asset != "BTC" || s.depositor_index.is_none() {
        return Err("only a co-signed Bitcoin deposit has a refund path".into());
    }
    if matches!(s.status.as_str(), "minted" | "redeemed" | "reclaimed") {
        return Err(format!("this deposit is {} — there is nothing to reclaim", s.status));
    }
    let coin = deposit_coin_at(&s.deposit_address)?;
    let value = coin["value_sats"].as_u64().ok_or("deposit coin value")?;
    let confs = coin["confirmations"].as_u64().unwrap_or(0);
    let week = u64::from(usdmd_node::btc_tx::DEPOSIT_REFUND_BLOCKS);
    let keep = value.saturating_sub(SWEEP_FEE_SATS);
    Ok(serde_json::json!({
        "sats": value, "fee_sats": SWEEP_FEE_SATS, "keep_sats": keep,
        "confirmations": confs, "opens_in_blocks": week.saturating_sub(confs),
        "dust": keep < usdmd_node::btc_payout::DUST_SATS,
    }))
}
off_ui_thread!(wallet_reclaim_deposit_quote => wallet_reclaim_deposit_quote_blocking(swap_id: String));

/// ⭐ §BR-2 — RECLAIM A DEPOSIT THAT NEVER MINTED, alone, after one week: the refund leaf (`<1008> CSV <D> CHECKSIG`)
/// pays the coin, less a fee, to a fresh vault address. Refused while the swap minted (the custody swept it) or before
/// 1,008 confirmations (Bitcoin itself would refuse it, BIP 68).
fn wallet_reclaim_deposit_blocking(swap_id: String) -> Result<serde_json::Value, String> {
    let mut list = read_swaps();
    let idx = list.iter().position(|s| s.swap_id == swap_id).ok_or("swap not found")?;
    if list[idx].asset != "BTC" {
        return Err("only a Bitcoin deposit has a refund path".into());
    }
    if matches!(list[idx].status.as_str(), "minted" | "redeemed" | "reclaimed") {
        return Err(format!("this deposit is {} — there is nothing to reclaim", list[idx].status));
    }
    let reserve_address = list[idx].deposit_address.clone();
    let d_blind = list[idx].mint_blind.ok_or("this swap has no mint blind")?;
    let index = list[idx].depositor_index.ok_or("this deposit has no depositor key (a pre-§BR-2 swap)")?;
    let (d_sk, d_x) = depositor_key_at(index)?;
    let (_leaf, out) = verified_deposit_leaf(&reserve_address, &d_blind, &d_x)?;
    let coin = deposit_coin_at(&reserve_address)?;
    let confs = coin["confirmations"].as_u64().unwrap_or(0);
    let week = u64::from(usdmd_node::btc_tx::DEPOSIT_REFUND_BLOCKS);
    if confs < week {
        return Err(format!("the refund opens after {week} confirmations — {} more Bitcoin blocks (about {:.1} days)", week - confs, (week - confs) as f64 / 144.0));
    }
    let txid = usdmd_node::btc_tx::txid_from_display_hex(coin["txid"].as_str().ok_or("deposit coin txid")?).ok_or("txid")?;
    let vout = coin["vout"].as_u64().ok_or("deposit coin vout")? as u32;
    let value = coin["value_sats"].as_u64().ok_or("deposit coin value")?;
    let fee = SWEEP_FEE_SATS;
    let keep = value.checked_sub(fee).filter(|k| *k >= usdmd_node::btc_payout::DUST_SATS).ok_or("the deposit is too small to pay its refund fee")?;
    let vault_index = vault_next_index(&read_cashouts());
    let to = vault_address_at(vault_index)?;
    let (_, to_spk) = usdmd_node::btc_tx::script_pubkey_for_address(&to).ok_or("vault address")?;
    let payout = usdmd_node::btc_tx::Payout {
        inputs: vec![usdmd_node::btc_tx::TxIn {
            txid,
            vout,
            value_sats: value,
            script_pubkey: usdmd_node::btc_tx::p2tr_script_pubkey(&out.output_x),
            sequence: usdmd_node::btc_tx::DEPOSIT_REFUND_BLOCKS,
        }],
        outputs: vec![usdmd_node::btc_tx::TxOut { value_sats: keep, script_pubkey: to_spk }],
    };
    let m = payout.sighash_script_path(0, &out.refund_hash).ok_or("refund sighash")?;
    let mut aux = [0u8; 32];
    rand::RngCore::fill_bytes(&mut rand::rngs::OsRng, &mut aux);
    let sig = usdmd_node::btc_tx::sign_sighash(&d_sk, &m, &aux).ok_or("refund signature")?; // CLASSICAL-CRYPTO-EXEMPT: the depositor's BIP-340 refund signature on Bitcoin (bridge endpoint)
    let witness = vec![sig.to_vec(), out.refund_leaf.clone(), usdmd_node::btc_tx::deposit_control_block(&out, false)];
    let raw = payout.serialize_with_witness(&[witness]).ok_or("serialize the refund")?;
    let agent = ureq::AgentBuilder::new().timeout(Duration::from_secs(20)).build();
    let v: serde_json::Value = agent
        .post(&format!("{}/btc_broadcast", node_url()))
        .send_json(serde_json::json!({ "raw_hex": hex::encode(&raw) }))
        .map_err(|e| format!("broadcast: {}", node_refusal(e)))?
        .into_json()
        .map_err(|e| format!("broadcast json: {e}"))?;
    let txid_out = v["txid"].as_str().ok_or("Bitcoin did not accept the refund yet — try again in a block")?.to_string();
    list[idx].status = "reclaimed".into();
    list[idx].reclaim = Some((vault_index, txid_out.clone()));
    write_swaps(&list);
    Ok(serde_json::json!({ "reclaimed": true, "txid": txid_out, "to": to, "sats": keep }))
}
off_ui_thread_approved!(wallet_reclaim_deposit => wallet_reclaim_deposit_blocking(swap_id: String) ; format!("Reclaim the Bitcoin deposit of swap {}", approval_short(&swap_id, 16)));

/// §BR-1 / spec §3.6 — CROWD PACING WITHOUT A PUBLIC FIGURE. Each of `n` pieces gets a delay (chain-time ms after now)
/// inside `[one proposer slot, PAY_AFTER_MAX_MS]`, uniformly random, with NO two in the same proposer slot and none in
/// a slot this wallet's pending pieces (`taken`, also as offsets after the tip) already occupy. So this wallet is at most
/// ONE output of any payout batch — ≤ 5 % of a batch whenever the batch holds ≥ 20 legs, the spec's bound, with nothing
/// read from any node (a served per-batch count would be a new metadata surface). A plan wider than the window's free
/// slots (> 1,438 pieces, 143.8 BTC at the smallest piece) reuses slots in a second pass — stated, not hidden.
fn distinct_pay_after_slots(n: usize, taken: &[u64], stretch: bool, rng: &mut impl rand::RngCore) -> Vec<u64> {
    let slot = usdmd_node::btc_payout::PROPOSER_SLOT_MS;
    let slots_total = usdmd_node::peg::PAY_AFTER_MAX_MS / slot; // slot k covers offsets [k·slot, (k+1)·slot)
    // §3.6: a withdrawal soon after a deposit is stretched toward the cap — its pieces draw only from the window's later
    // half, so a deposit and a quick exit never sit in neighbouring batches
    let first = if stretch { (slots_total / 2).max(1) } else { 1 };
    let busy: std::collections::HashSet<u64> = taken.iter().map(|t| t / slot).collect();
    let mut free: Vec<u64> = (first..slots_total).filter(|k| !busy.contains(k)).collect();
    if free.is_empty() {
        free = (first..slots_total).collect();
    }
    // Fisher–Yates over the free slots, then one uniform offset inside each chosen slot
    for i in (1..free.len()).rev() {
        let j = (rng.next_u64() % (i as u64 + 1)) as usize;
        free.swap(i, j);
    }
    (0..n).map(|i| free[i % free.len()] * slot + rng.next_u64() % slot).collect()
}

fn plan_cash_out(usdm_amount: f64, asset: &str, payout_to: &str, fast: bool) -> Result<CashOutPlan, String> {
    if !(usdm_amount > 0.0) {
        return Err("enter a USDm amount above 0".into());
    }
    let asset = asset.trim().to_uppercase();
    if asset != "BTC" && asset != "XMR" {
        return Err("a cash-out pays Bitcoin or Monero".into());
    }
    if asset == "XMR" && payout_to.trim().is_empty() {
        return Err("enter the Monero address to receive the release".into());
    }
    if fast && auto_opsec_on() {
        return Err(AUTO_OPSEC_REFUSES_FAST.into());
    }
    let (price, scale, epoch) = price_mark_for(&asset)?;
    let usdm_atomic = u128::from(usdm_to_atomic(usdm_amount)?);
    // ⭐ §19.4: a piece is ONE dollar rung (`peg_pool::USD_DENOMS`), burned and released at its batch's price. Each piece
    // costs two flat network fees (§BR-14): its staging payment and its claim's burn — the pieces are cut from what is left
    // after them, so the burns plus their fees never exceed the amount asked for. Two passes settle the count.
    let fee = u128::from(P2P_FEE_ATOMIC) * 2;
    if usdm_atomic > u128::from(u64::MAX) {
        return Err("that amount is larger than any cash-out can carry".into());
    }
    let legs_after = |fees: u128| usdmd_node::peg_pool::split_to_usd_denoms(usdm_atomic.saturating_sub(fees) as u64).0;
    let first = legs_after(0);
    let mut legs = legs_after(fee * first.len() as u128);
    let again = legs_after(fee * legs.len() as u128);
    if again.len() <= legs.len() {
        legs = again;
    }
    if legs.is_empty() {
        return Err(format!("{usdm_amount} USDm is below the smallest cash-out piece ($10 plus its network fees) — it stays USDm"));
    }
    let existing = read_cashouts();
    let mut next_vault = vault_next_index(&existing);
    let tip = node_tip_height();
    // a pay-after is a moment on the chain clock, never a count of blocks (the chain runs at its mesh's rate)
    let chain_now = node_chain_time_ms();
    if chain_now == 0 && !fast {
        return Err("your node has not reported the chain's clock yet — try again in a moment".into());
    }
    let mut pieces = Vec::with_capacity(legs.len());
    let mut burned_total: u128 = 0;
    // every moment this wallet's still-pending pieces already wait for — a new piece never joins their batches either
    let taken: Vec<u64> = existing
        .iter()
        .flat_map(|p| p.pieces.iter())
        .filter(|c| c.status == "pending" && c.pay_after > chain_now)
        .map(|c| c.pay_after - chain_now)
        .collect();
    // §3.6 deposit-then-quick-withdraw: a deposit of this wallet minted inside the last 24 h stretches every piece toward
    // the cap (read from this device's own swap records — nothing is asked of a node)
    let key = current_key_id_hex().unwrap_or_default();
    let recent_deposit = read_swaps().iter().any(|r| {
        r.key_id_hex == key
            && r.status == "minted"
            && r.mint_height > 0
            && now_ms().saturating_sub(r.created_ms) < usdmd_node::peg::PAY_AFTER_MAX_MS
    });
    let mut slots = distinct_pay_after_slots(legs.len(), &taken, recent_deposit, &mut rand::rngs::OsRng);
    for leg in legs {
        burned_total += u128::from(leg);
        // what the piece pays at today's price (the batch's price decides it; every piece of its rung in its batch is paid alike)
        let release_now = u64::try_from(u128::from(leg).saturating_mul(scale) / price.max(1))
            .map_err(|_| "the chain's price puts this piece past one payout — try a smaller amount")?;
        let (payout, vault_index) = if payout_to.trim().is_empty() {
            let a = vault_address_at(next_vault)?;
            next_vault += 1;
            (a, Some(next_vault - 1))
        } else {
            if asset == "BTC" {
                refuse_deposit_sender(payout_to.trim())?;
            }
            (payout_to.trim().to_string(), None)
        };
        // the privacy delay: uniform inside [next batch, 24 h] of chain time, drawn per piece from the OS CSPRNG, each
        // piece in its OWN payout batch (§3.6 crowd pacing: this wallet is at most one output of any batch — see
        // `distinct_pay_after_slots`; no public figure is read, so pacing adds no served count)
        let pay_after = if fast { 0 } else { chain_now + slots.pop().unwrap_or(usdmd_node::btc_payout::PROPOSER_SLOT_MS) };
        pieces.push(CashPiece {
            piece_atomic: release_now,
            burn_atomic: leg,
            payout_to: payout,
            vault_index,
            pay_after,
            status: "pending".into(),
            swap_id: None,
            escrow_value: 0,
            escrow_seed_hex: String::new(),
            escrow_cm_hex: String::new(),
            escrow_nf_hex: String::new(),
        });
    }
    let fees_total = fee * pieces.len() as u128;
    let remainder_usdm = (usdm_atomic.saturating_sub(burned_total).saturating_sub(fees_total)) as f64 / 1e8;
    let plan_id = format!("CASH-{}", hex::encode(&blake3::hash(&[&usdm_atomic.to_le_bytes()[..], &tip.to_le_bytes()[..], &rand::random::<[u8; 8]>()[..]].concat()).as_bytes()[..6]));
    Ok(CashOutPlan {
        plan_id,
        key_id_hex: current_key_id_hex().unwrap_or_default(),
        asset,
        usdm_requested: usdm_amount,
        price: price.to_string(),
        scale: scale as u64,
        price_epoch: epoch,
        remainder_usdm,
        fast,
        created_ms: std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map(|d| d.as_millis() as u64).unwrap_or(0),
        created_height: tip,
        pieces,
    })
}

/// ⛔ ONE ADVANCE AT A TIME PER PROCESS (lane funds-brb27, 2026-11-01). MEASURED on the shipped cash-out flow (F6, c5.log):
/// `wallet_cash_out` was still proving piece 1's escrow payment (7 s) when the page's one-second `wallet_cash_out_progress`
/// poll read the plan from disk — piece 1 still "pending" — and paid it AGAIN from the same note; the node refused the
/// second spend as POSITIVELY SPENT (slot 0) and the plan recorded the piece as failed while its escrow was in fact paid.
/// Every advance now runs under this lock and re-reads the plan it was handed from the store first, so a caller holding a
/// stale copy sees what the other caller already did. Funds-safe before (the node refused the double spend); the user saw a
/// false "failed" and a stuck piece.
static CASHOUT_ADVANCE: Mutex<()> = Mutex::new(());

/// Burn every piece of `plan` that can be funded now; a piece the notes cannot fund yet (change in flight) stays pending
/// for the progress poll. Writes the plan after each piece so a crash loses nothing.
fn advance_cash_out(plan: &mut CashOutPlan) {
    let _one_at_a_time = CASHOUT_ADVANCE.lock().unwrap_or_else(|e| e.into_inner());
    // the store is the truth about what another caller already did with this plan
    if let Some(stored) = read_cashouts().into_iter().find(|p| p.plan_id == plan.plan_id) {
        *plan = stored;
    }
    for i in 0..plan.pieces.len() {
        let c = plan.pieces[i].clone();
        match c.status.as_str() {
            // ⭐ §19.4 — STAGE: an ordinary payment of the rung (plus its claim's fee) to this wallet under the piece's
            // one-time key
            "pending" => match stage_pay_piece(&plan.plan_id, i, &c) {
                Ok((value, seed, cm, nf)) => {
                    let p = &mut plan.pieces[i];
                    p.escrow_value = value;
                    p.escrow_seed_hex = hex::encode(usdmd_node::spend_frontier::digest_to_lane_bytes(&seed));
                    p.escrow_cm_hex = hex::encode(cm);
                    p.escrow_nf_hex = hex::encode(nf);
                    p.status = "staged".into();
                }
                Err(why) => {
                    // a funding gap is not a failure: the piece waits for the change to settle; a node refusal is recorded
                    // (and a note whose membership witness has not arrived yet is the same gap: it is spendable a poll later)
                    if why.contains("not enough") || why.contains("split across notes") || why.contains("in flight") || why.contains("not ready yet") {
                        break;
                    }
                    plan.pieces[i].status = format!("failed:{why}");
                }
            },
            // CLAIM: the staged note folded under an epoch anchor — prove and relay its anonymous claim (NOT_YET until then)
            "staged" => match claim_piece(&plan.plan_id, i, &c) {
                Ok(true) => plan.pieces[i].status = "claimed".into(),
                Ok(false) => {}
                Err(why) => plan.pieces[i].status = format!("failed:{why}"),
            },
            // custody burns it at its batch; a node that forgot the claim (a restart) gets it again, from the same note
            "claimed" => match piece_burned(&c.escrow_nf_hex) {
                Some(true) => plan.pieces[i].status = "redeemed".into(),
                Some(false) if claim_held(&c.escrow_nf_hex) == Some(false) => plan.pieces[i].status = "staged".into(),
                _ => continue,
            },
            _ => continue,
        }
        let mut all = read_cashouts();
        if let Some(p) = all.iter_mut().find(|p| p.plan_id == plan.plan_id) {
            *p = plan.clone();
        }
        write_cashouts(&all);
    }
}

/// ⭐ §19.4 — the one-time key of plan `plan_id`'s piece `i`: its STAGED note's spend key, from this device's 24 words (a
/// restore re-derives it). A note under it is no ordinary send's input (the wallet's selector scans under its own spend
/// key), so a staged piece is never spent by accident; spending it on purpose takes the piece back.
fn stage_key_for(plan_id: &str, i: usize) -> Result<[u8; 32], String> {
    let phrase = std::fs::read_to_string(node_data_dir().join("seed"))
        .ok()
        .map(|s| s.trim().to_string())
        .filter(|s| !s.is_empty())
        .ok_or("a private cash-out needs this device's persisted 24 words — restore once more to persist them")?;
    let mut h = blake3::Hasher::new_derive_key("MUSD/cashout-stage-key/v1");
    h.update(phrase.as_bytes());
    h.update(plan_id.as_bytes());
    h.update(&(i as u64).to_le_bytes());
    Ok(*h.finalize().as_bytes())
}

/// ⭐ §19.4 — STAGE A PIECE: an ORDINARY payment of exactly the piece's rung plus its claim's network fee to this wallet's own
/// scan key under the piece's one-time spend key — byte-identical to every other payment, so staging adds no metadata.
/// Returns the staged note's value, seed (recovered from the payee note with this wallet's own key), commitment and
/// nullifier.
fn stage_pay_piece(plan_id: &str, i: usize, c: &CashPiece) -> Result<(u64, Digest4, [u8; 32], [u8; 32]), String> {
    let key = stage_key_for(plan_id, i)?;
    let spk_e = usdmd_node::cashout_ticket::escrow_spk(&key);
    let value = c.burn_atomic + P2P_FEE_ATOMIC;
    let (b, scan_ek, loc_sk) = {
        let g = WALLET.lock().unwrap_or_else(|e| e.into_inner());
        let w = g.as_ref().ok_or("no wallet open")?;
        (w.b, w.scan_ek.clone(), w.loc_sk)
    };
    let j = current_receive_index(&loc_sk);
    let address = pq::receive_address(&b, &scan_ek, &spk_e, &loc_sk, j).ok_or("the staging address does not encode")?;
    let resp = do_transfer_atomic(address, value)?;
    let note = resp
        .get("recipient_note_hex")
        .and_then(|v| v.as_str())
        .and_then(|h| hex::decode(h).ok())
        .ok_or("the staging payment returned no note")?;
    let (amt, seed) = usdmd_node::faucet::open_note(&note, &own_scan_dk()?, &spk_e).ok_or("the staged note does not open to this wallet")?;
    if amt != value {
        return Err("the staged note holds another amount".into());
    }
    let cm = usdmd_node::spend_frontier::leaf_to_cm_bytes(usdmd_node::cashout_ticket::escrow_cm(&key, value, &seed));
    if note.get(..32) != Some(cm.as_slice()) {
        return Err("the staged note is not the note this key names".into());
    }
    Ok((value, seed, cm, usdmd_node::cashout_ticket::escrow_nf(&key, value, &seed)))
}

/// ⭐⭐ §19.4 — THE UNLINKABLE CLAIM: once the staged note has folded under an epoch anchor, this wallet proves the burn of
/// exactly the piece's rung into the ticket bound to its destination and pay-after (the change is zero), with the note's
/// record-free member leg anchored to that EPOCH ANCHOR (built by this wallet's own node), and hands the request to its
/// node, which relays it to custody. Custody holds it until the piece's batch, then burns it exactly as built — the proof
/// binds the destination — and pays the batch. Custody never learns the note, the wallet or the staging time; the device may
/// be off from here on. `Ok(false)` while the note is not under an anchor yet or the chain has no final custody key.
fn claim_piece(plan_id: &str, i: usize, c: &CashPiece) -> Result<bool, String> {
    let key = stage_key_for(plan_id, i)?;
    let seed = hex::decode(&c.escrow_seed_hex)
        .ok()
        .and_then(|b| usdmd_node::spend_frontier::digest_from_lane_bytes(&b))
        .ok_or("the staged note's seed is not recorded")?;
    let value = c.escrow_value;
    let atomic = c.burn_atomic;
    let change_amt = value.checked_sub(atomic + P2P_FEE_ATOMIC).ok_or("the staged note does not cover its piece and fee")?;
    let owner = usdmd_node::cashout_ticket::escrow_owner(&key, &seed);
    let cm = usdmd_node::spend_frontier::leaf_to_cm_bytes(usdmd_node::cashout_ticket::escrow_cm(&key, value, &seed));
    let nullifier = usdmd_node::cashout_ticket::escrow_nf(&key, value, &seed);
    let (my_ek, spk, loc_sk) = {
        let g = WALLET.lock().unwrap_or_else(|e| e.into_inner());
        let w = g.as_ref().ok_or("no wallet open")?;
        (w.scan_ek.clone(), w.note_spk, w.loc_sk)
    };
    let agent = ureq::AgentBuilder::new().timeout(Duration::from_secs(60)).build();
    let post = |path: &str, body: serde_json::Value| -> Result<serde_json::Value, String> {
        agent
            .post(&format!("{}{path}", node_url()))
            .send_json(body)
            .map_err(|e| format!("the node did not answer: {}", node_refusal(e)))?
            .into_json()
            .map_err(|e| format!("the node's answer: {e}"))
    };
    let field = |v: &serde_json::Value, k: &str| v.get(k).and_then(|x| x.as_str()).map(str::to_string);
    // DB-363: ONE blinding draw for the burn's cross-bind and the leg's leaf commit
    let lc_blind = usdm_decider::whir_rec_block::fresh_lc_blind().ok_or("the OS random source refused a blinding draw — nothing was built")?;
    // CHAIN-OBJECT: this only BUILDS the claim (the burn carrier and its leg) the PegOut object carries; the burn applies at
    // the fold on every node from that object in the batch's block — nothing here moves a value.
    let leg = post(
        "/claim_member_leg",
        serde_json::json!({
            "cm_hex": hex::encode(cm),
            "usdm_nullifier": hex::encode(nullifier),
            "blind_hex": hex::encode(usdmd_node::spend_frontier::digest_to_lane_bytes(&lc_blind)),
            "pay_after": c.pay_after,
        }),
    )?;
    let (Some(mem_carrier), Some(mem_tip)) = (field(&leg, "membership_carrier_hex"), field(&leg, "membership_tip_hex")) else {
        return Ok(false); // NOT_YET: the next epoch anchor (≤ 10 min) holds the note (a fast piece: its record has not folded yet)
    };
    // the change (zero) is a fresh note to this wallet under its own clue at a reserved index — no ownerless credit
    let (change_note, change_opening) =
        pq::seal_note_full_asset(&my_ek, &spk, change_amt, pq::USDM_ASSET_TAG).ok_or("the claim's change could not be sealed — nothing was built")?;
    let change_cm_pre: [u8; 32] = change_note.get(..32).and_then(|c| <[u8; 32]>::try_from(c).ok()).ok_or("the change note has no commitment")?;
    let ((_dom, j), _no_self, reservation) = dense_locators_for(false, &[nullifier])?;
    let recs = self_note_clue_records(&loc_sk, &[change_cm_pre], &[Some(j)]);
    let clue = recs.get(34..).filter(|c| !c.is_empty()).map(<[u8]>::to_vec).ok_or("the change clue could not be derived")?;
    let (ticketed_commit, ticket_parts_hex, leg_blind) = match cashout_ticket_for(&nullifier, c.payout_to.trim(), c.pay_after, atomic, &clue) {
        Ok(t) => t,
        Err(why) if why.contains("custody key for this payout's hour is not ready") => return Ok(false),
        Err(why) => return Err(why),
    };
    // CHAIN-OBJECT: the claim's burn is PROVEN here and carried by the PegOut object; it applies only at the fold, from the block.
    let burn_out_opening = usdmd_node::cashout_ticket::burn_out_opening(&ticketed_commit, &leg_blind);
    let (carrier, cms, nf, leaf_commit, burn_commit) = pq_spend::build_burn_carrier_committed(
        value, owner, atomic, P2P_FEE_ATOMIC, burn_out_opening, change_opening, lc_blind, usdmd_node::peg::peg_out_burn_blind(&leg_blind),
    )
    .ok_or("the claim's burn carrier did not build")?;
    if burn_commit != usdmd_node::peg::peg_out_burn_commit(u128::from(atomic), &leg_blind)
        || !usdm_decider::whir_rec_block::verify_burn_validity_committed_bytes(&carrier, cms[0], cms[1], nf, leaf_commit, burn_commit, P2P_FEE_ATOMIC)
        || leaf4_to_bytes(nf) != nullifier
        || leaf4_to_bytes(cms[1]) != change_cm_pre
        || field(&leg, "leaf_commit_hex").as_deref() != Some(hex::encode(leaf4_to_bytes(leaf_commit)).as_str())
    {
        return Err("the claim did not verify against its own binding — nothing was relayed".into());
    }
    let r = post(
        "/peg_out_execute",
        serde_json::json!({
            "usdm_nullifier": hex::encode(nullifier),
            "out0_cm": hex::encode(leaf4_to_bytes(cms[0])),
            "out1_cm": hex::encode(change_cm_pre),
            "burn_carrier_hex": hex::encode(&carrier),
            "burn_amount": atomic,
            "change_note_payload": hex::encode(change_note),
            "redeem_to": c.payout_to.trim(),
            "pay_after": c.pay_after,
            "membership_carrier_hex": mem_carrier,
            "membership_tip_hex": mem_tip,
            "membership_leaf_commit": hex::encode(leaf4_to_bytes(leaf_commit)),
            "note_clue_hex": hex::encode(&clue),
            "ticketed_commit": hex::encode(ticketed_commit),
            "ticket_parts_hex": ticket_parts_hex,
            "leg_blind_hex": hex::encode(usdmd_node::spend_frontier::digest_to_lane_bytes(&leg_blind)),
            "relay_after_ms": claim_relay_moment_ms(c.pay_after, node_chain_time_ms(), &mut rand::rngs::OsRng),
        }),
    )?;
    let held = r.get("redeemed").and_then(|b| b.as_bool()) == Some(true)
        || r.get("published").and_then(|b| b.as_bool()) == Some(true)
        || r.get("gathering").and_then(|b| b.as_bool()) == Some(true);
    if held {
        reservation.commit(nullifier);
        return Ok(true);
    }
    match r.get("outcome").and_then(|s| s.as_str()) {
        Some(outcome) => Err(format!("the node refused the claim: {outcome}")),
        None => Err("the node refused the claim and named no reason".into()),
    }
}

/// ⭐ §19.4 — THE CLAIM'S RELAY MOMENT (unix ms): uniform between now and ten minutes before the piece's batch (the start of
/// the hour-epoch after the one its pay-after falls in, on the chain clock `chain_now`), so custody cannot group one
/// cash-out's pieces by when they reached it — each piece of a plan draws its own. The node holds the claim until then (it
/// runs on with the window closed). A "fast" piece (pay-after 0) relays at once.
fn claim_relay_moment_ms(pay_after: u64, chain_now: u64, rng: &mut impl rand::RngCore) -> u64 {
    // a clock before 1970 reads as 0 = relay at once (never later than the batch)
    let now = std::time::SystemTime::now().duration_since(std::time::UNIX_EPOCH).map_or(0, |d| d.as_millis() as u64);
    if pay_after == 0 {
        return now;
    }
    let epoch = usdmd_node::epoch_deal_tx::EPOCH_MS;
    let batch_ms = (pay_after / epoch + 1) * epoch;
    let window_ms = batch_ms.saturating_sub(chain_now).saturating_sub(600_000);
    if window_ms == 0 {
        return now;
    }
    now + rng.next_u64() % window_ms
}

/// ⭐ §19.4 — does this wallet's node still hold the claim of `nf_hex` (relaying it to custody until its batch), or has the
/// chain burned it? `Some(false)` = neither: a restarted node forgot it, and the wallet relays it again.
fn claim_held(nf_hex: &str) -> Option<bool> {
    let v: serde_json::Value = ureq::AgentBuilder::new()
        .timeout(Duration::from_secs(8))
        .build()
        .post(&format!("{}/peg_out_execute", node_url()))
        .send_json(serde_json::json!({ "usdm_nullifier": nf_hex }))
        .ok()?
        .into_json()
        .ok()?;
    let yes = |k: &str| v.get(k).and_then(|b| b.as_bool()) == Some(true);
    Some(yes("redeemed") || yes("published") || yes("gathering"))
}

/// §19.4 — has the chain applied the piece's burn? `None` when the node did not answer.
fn piece_burned(nf_hex: &str) -> Option<bool> {
    let v: serde_json::Value = ureq::AgentBuilder::new()
        .timeout(Duration::from_secs(8))
        .build()
        .post(&format!("{}/reserve_release_status", node_url()))
        .send_json(serde_json::json!({ "usdm_nullifier": nf_hex }))
        .ok()?
        .into_json()
        .ok()?;
    v.get("burned").and_then(|b| b.as_bool())
}

/// A-F35 — what ONE Bitcoin piece pays in miner fee when it is alone in its payout, in sats, at this wallet's node's own
/// reading of Bitcoin's fee market (`/btc_cashout_fee_quote`). The legs of a payout share its fee equally, so this is the
/// most a piece pays at that rate; `None` when the node has no Bitcoin reading (or did not answer) — then the fee is named
/// without a figure, never as zero.
fn btc_alone_fee_sats() -> Option<u64> {
    let v: serde_json::Value = ureq::AgentBuilder::new()
        .timeout(Duration::from_secs(8))
        .build()
        .get(&format!("{}/btc_cashout_fee_quote", node_url()))
        .call()
        .ok()?
        .into_json()
        .ok()?;
    v.get("alone_fee_sats").and_then(|f| f.as_u64())
}

/// `btc_fee`: the node's reading from [`btc_alone_fee_sats`], read ONCE by the caller for every plan it renders (`None`: the
/// node has no reading, or no plan in the call is a Bitcoin one).
fn plan_json(p: &CashOutPlan, tip: u64, chain_now: u64, btc_fee: Option<u64>) -> serde_json::Value {
    let burned = p.pieces.iter().filter(|c| matches!(c.status.as_str(), "requested" | "redeemed" | "staged" | "claimed")).count();
    let pending = p.pieces.iter().filter(|c| c.status == "pending").count();
    let last_pay_after = p.pieces.iter().map(|c| c.pay_after).max().unwrap_or(0);
    let ms_left = last_pay_after.saturating_sub(chain_now);
    let is_btc = p.asset.eq_ignore_ascii_case("BTC");
    serde_json::json!({
        "plan_id": p.plan_id, "asset": p.asset, "usdm_requested": p.usdm_requested, "remainder_usdm": p.remainder_usdm,
        "fast": p.fast, "price": p.price, "scale": p.scale, "price_epoch": p.price_epoch, "created_height": p.created_height,
        "pieces": p.pieces, "parts_total": p.pieces.len(), "parts_sent": burned, "parts_pending": pending,
        "network_fee_usdm": (2.0 * P2P_FEE_ATOMIC as f64 / 1e8) * p.pieces.len() as f64, // §19.4: the staging payment + the claim
        // A-F21 / A-F35: each Bitcoin piece arrives as its release less its equal share of the miner fee of the payout that
        // pays it (the reserve never pays a fee). Shown before the user confirms (ADOPTABLE: every cost named before
        // acting) as the MOST a piece pays at the node's current reading — the fee of a payout it is alone in; pieces that
        // share a payout pay less. `bitcoin_fee_known` is false when the node has no Bitcoin reading: the page then names
        // the fee without a figure. `bitcoin_fee_max_share_divisor`: a piece whose share would pass 1/that of it waits.
        "bitcoin_fee_sats": if is_btc { btc_fee.unwrap_or(0) * p.pieces.len() as u64 } else { 0 },
        "bitcoin_fee_sats_per_piece": if is_btc { btc_fee.unwrap_or(0) } else { 0 },
        "bitcoin_fee_known": !is_btc || btc_fee.is_some(),
        "bitcoin_fee_is_upper_bound": is_btc,
        "bitcoin_fee_max_share_divisor": usdmd_node::btc_payout::FEE_SHARE_MAX_DIVISOR,
        "about_hours_left": ms_left as f64 / 3_600_000.0,
        "tip": tip,
    })
}

/// CASH OUT (the "Cash out" button): price, split, draw delays, burn what can be burned now, and answer the plan.
fn wallet_cash_out_blocking(usdm_amount: f64, asset: String, payout_to: String, fast: bool) -> Result<serde_json::Value, String> {
    // §19.4 / §19.5: Bitcoin and Monero cash out alike — dollar pieces, each staged and claimed, burned and paid at its batch
    let log_key_hex = {
        let g = WALLET.lock().unwrap_or_else(|e| e.into_inner());
        let w = g.as_ref().ok_or("no wallet open")?;
        hex::encode(wallet_log_key_id(&w.scan_ek))
    };
    let _ = settle_pending_redeems(&log_key_hex);
    let mut plan = plan_cash_out(usdm_amount, &asset, &payout_to, fast)?;
    let mut all = read_cashouts();
    all.push(plan.clone());
    write_cashouts(&all);
    advance_cash_out(&mut plan);
    let tip = node_tip_height();
    let fee = owe_interface_fee(interface_fee(usdm_to_atomic(usdm_amount)?, FEE_BPS_CASH)); // §BR-12: cash out 0.10 %
    let btc_fee = if plan.asset.eq_ignore_ascii_case("BTC") { btc_alone_fee_sats() } else { None };
    let mut out = plan_json(&plan, tip, node_chain_time_ms(), btc_fee);
    out["app_fee_usdm"] = serde_json::json!(fee as f64 / 1e8);
    Ok(out)
}
off_ui_thread_approved!(wallet_cash_out => wallet_cash_out_blocking(usdm_amount: f64, asset: String, payout_to: String, fast: bool) ; format!(
    "Cash out {usdm_amount} USDm to {} paid to {}{}",
    approval_short(&asset, 8),
    if payout_to.trim().is_empty() { "your vault".to_string() } else { approval_short(&payout_to, 18) },
    if fast { " (fast, less private)" } else { "" }
));

/// The dollars-first PREVIEW of a cash-out (no burn): the pieces, the delay window, the remainder that stays USDm.
fn wallet_cash_out_quote_blocking(usdm_amount: f64, asset: String, payout_to: String, fast: bool) -> Result<serde_json::Value, String> {
    let plan = plan_cash_out(usdm_amount, &asset, &payout_to, fast)?;
    let btc_fee = if plan.asset.eq_ignore_ascii_case("BTC") { btc_alone_fee_sats() } else { None };
    Ok(plan_json(&plan, plan.created_height, node_chain_time_ms(), btc_fee))
}
off_ui_thread!(wallet_cash_out_quote => wallet_cash_out_quote_blocking(usdm_amount: f64, asset: String, payout_to: String, fast: bool));

/// PROGRESS (the poll, and the "Send the rest now" switch when `fast_now`): settle redeems the chain carried, burn the
/// pieces that can be funded now, re-draw every still-pending piece's delay to the next batch when asked, and answer every
/// plan with honest counts ("2 of 3 parts sent · about 4 hours left").
fn wallet_cash_out_progress_blocking(fast_now: Option<String>) -> Result<serde_json::Value, String> {
    if fast_now.is_some() && auto_opsec_on() {
        return Err(AUTO_OPSEC_REFUSES_FAST.into());
    }
    let log_key_hex = {
        let g = WALLET.lock().unwrap_or_else(|e| e.into_inner());
        let w = g.as_ref().ok_or("no wallet open")?;
        hex::encode(wallet_log_key_id(&w.scan_ek))
    };
    let _ = settle_pending_redeems(&log_key_hex);
    rewards_btc_tick(); // §BR-8: the reward tally's cash-out, on the same poll
    let swaps = read_swaps();
    let mut all = read_cashouts();
    for plan in all.iter_mut() {
        if fast_now.as_deref() == Some(plan.plan_id.as_str()) {
            for c in plan.pieces.iter_mut().filter(|c| c.status == "pending") {
                c.pay_after = 0;
            }
            plan.fast = true;
        }
        for c in plan.pieces.iter_mut() {
            if let Some(id) = &c.swap_id {
                if let Some(s) = swaps.iter().find(|s| &s.swap_id == id) {
                    if s.status == "redeemed" {
                        c.status = "redeemed".into();
                    } else if s.status == "expired" {
                        c.status = "pending".into();
                        c.swap_id = None;
                    }
                }
            }
        }
    }
    write_cashouts(&all);
    for plan in all.iter_mut() {
        if plan.pieces.iter().any(|c| matches!(c.status.as_str(), "pending" | "staged" | "claimed")) {
            advance_cash_out(plan);
        }
    }
    let tip = node_tip_height();
    let all = read_cashouts();
    let chain_now = node_chain_time_ms();
    let btc_fee = if all.iter().any(|p| p.asset.eq_ignore_ascii_case("BTC")) { btc_alone_fee_sats() } else { None };
    Ok(serde_json::json!({ "plans": all.iter().rev().map(|p| plan_json(p, tip, chain_now, btc_fee)).collect::<Vec<_>>(), "tip": tip }))
}
off_ui_thread!(wallet_cash_out_progress => wallet_cash_out_progress_blocking(fast_now: Option<String>));


/// READ-ONLY Sell quote: asks the node what burning `usdm_amount` would net, AFTER the dynamic reserve-protection
/// fee (which rises as the reserve is drawn down). Lets the Sell form show the user the live fee + net BEFORE they
/// confirm, so the "draining the reserve is unprofitable" economics is visible. Mutates nothing.
fn wallet_sell_quote_blocking(usdm_amount: f64, asset: String) -> Result<serde_json::Value, String> {
    // DB-319: the quote is for the burn that will happen — a whole amount, or a legible refusal; never a rounded one.
    let burn_units = whole_usdm_units(usdm_amount)?;
    let _ = &asset;
    // The withdrawal fee is the governance-tunable reserve-protection BAND (it rises as the reserve is drawn down).
    // Show the CONSERVATIVE (max-band) estimate read live from /get_governance — a read-only, node-first governance
    // read that exposes NO confidential reserve state; the exact fee is applied node-side at execute time.
    let agent = ureq::AgentBuilder::new().timeout(Duration::from_secs(8)).build();
    let gov: serde_json::Value = agent
        .post(&format!("{}/get_governance", node_url()))
        .send_json(serde_json::json!({}))
        .map_err(|e| format!("quote governance: {}", node_refusal(e)))?
        .into_json()
        .map_err(|e| format!("quote json: {e}"))?;
    let fee_bps = gov.get("withdraw_fee_max_bps").and_then(|u| u.as_u64()).unwrap_or(0);
    let gross = burn_units; // 1:1 peg (unit price on testnet)
    let fee = gross.saturating_mul(fee_bps) / 10_000;
    let net = gross.saturating_sub(fee);
    Ok(serde_json::json!({
        "burn": burn_units, "reserve": 0, "gross": gross,
        "net": net, "fee": fee, "fee_bps": fee_bps
    }))
}
off_ui_thread!(wallet_sell_quote => wallet_sell_quote_blocking(usdm_amount: f64, asset: String));

/// PEG-OUT e2e (Buy-USDm REDEEM/BURN): the reverse of the mint. Computes the minted note's REAL public nullifier
/// locally (the spend secret never leaves the wallet), gathers a real bonded threshold from the mesh, and POSTs
/// `/peg_out` — which verifies the threshold and RECORDS the nullifier spent, destroying the note. The next
/// balance scan excludes the now-spent note, so the USDm balance FALLS and the user's deposit is released to
/// their external address. TEST-GATED (only the external withdrawal broadcast is simulated). Proves a user can
/// always exit — funds are never trapped.
/// DB-373: the IPC command is [`wallet_redeem_swap`], approved per action (it burns USDm and pays an EXTERNAL address).
fn wallet_redeem_swap_blocking(swap_id: String, redeem_to: String) -> Result<serde_json::Value, String> {
    let mut list = read_swaps();
    let idx = list.iter().position(|s| s.swap_id == swap_id).ok_or("swap not found")?;
    if list[idx].status != "minted" {
        return Err("this swap is not minted — nothing to redeem".to_string());
    }
    let usdm_out = list[idx].usdm_out;
    let asset = list[idx].asset.clone();
    let redeem_addr = if redeem_to.trim().is_empty() { format!("test-redeem-{swap_id}") } else { redeem_to.trim().to_string() };
    // Redeem = burn THIS swap's USDm via the SOUND burn-verified peg-out (the SAME path as a general Sell): the
    // wallet builds a WELDED burn carrier proving it owns + destroys the USDm, and the node VERIFIES that carrier
    // before releasing the reserve to `redeem_addr`. Funds are never trapped — a user can always exit — and the
    // reserve can only ever release for USDm actually burned (no drain).
    let sell = wallet_sell_usdm_blocking(usdm_out, asset, redeem_addr.clone())?;
    list[idx].status = "redeemed".to_string();
    write_swaps(&list);
    Ok(serde_json::json!({ "ok": true, "usdm_burned": usdm_out, "redeem_to": redeem_addr, "sell": sell }))
}
// DB-373: a redeem burns USDm and pays an EXTERNAL address — approved per action, naming that address.
off_ui_thread_approved!(wallet_redeem_swap => wallet_redeem_swap_blocking(swap_id: String, redeem_to: String) ; format!(
    "Redeem swap {} and pay out to {}",
    approval_short(&swap_id, 12),
    approval_short(&redeem_to, 18)
));

/// Live SWAP-STATUS tracking — advances a swap's stage against the chain so the UI mirrors reality (never a
/// cached guess). Re-checks the reserve quorum (awaiting_reserve → awaiting_deposit once validators bond) and
/// detects the MINT: an owned note of the expected USDm amount landing at/after the swap's creation height ⇒
/// `minted`. Returns the full record so the tracker shows the current stage + swap_id.
fn wallet_swap_status_blocking(swap_id: String) -> Result<serde_json::Value, String> {
    let key_id_hex = current_key_id_hex().ok_or_else(|| "no wallet open".to_string())?;
    // Refresh the owned set (delta scan) so a just-landed mint note is visible.
    let _ = wallet_balance_impl();
    // DB-307: the commitments this wallet owns; the swap's mint is detected by ITS OWN note, never by amount + height.
    let owned_cms: HashSet<[u8; 32]> = owned_note_ids().into_iter().map(|(_, _, cm)| cm).collect();
    let mut swaps = read_swaps();
    let rec = swaps
        .iter_mut()
        .find(|s| s.swap_id == swap_id && s.key_id_hex == key_id_hex)
        .ok_or_else(|| "swap not found".to_string())?;
    if rec.status != "minted" && rec.status != "redeemed" {
        // The mint lands as an owned note of exactly usdm_out, at/after the swap's creation height. ('redeemed'
        // is terminal — the note is burned, so it must never be re-detected as a fresh mint.)
        // ⭐ DB-307: the mint is THIS swap's own note (`mint_note`, sealed once at creation and named by every poll), so
        // it has landed exactly when that commitment is owned. It was "an owned note of usdm_out at/after the creation
        // height", over a field that is `u64::MAX` or a record address for most notes, so any note of the same amount
        // the user already held marked the swap minted. A record from before `mint_note` existed stays where it is
        // (no false "minted"; the balance still shows the money).
        // ROOT-LAYER: the swap record carries the one fact that identifies its mint.
        // MEASURED: READ (the same `height >= since` defect as the settle watch; db307 pin RED there).
        // MUST-STAY-GREEN: a swap whose mint note lands reads minted; 'redeemed' stays terminal.
        let minted = rec
            .mint_note
            .as_ref()
            .is_some_and(|(note, _)| note.len() >= 32 && owned_cms.contains(&<[u8; 32]>::try_from(&note[..32]).unwrap_or([0u8; 32])));
        if minted {
            owe_cash_in_fee(rec); // §BR-12: cash in 0.10 %, once, the moment the deposit mints
            rec.status = "minted".to_string();
            rec.mint_height = LAST_TIP_SEEN.lock().unwrap_or_else(|e| e.into_inner()).map(|(h, _)| h).unwrap_or(rec.created_height);
        } else if rec.status == "awaiting_reserve" {
            // A quorum may have formed since — re-derive the deposit address so the user can now deposit.
            let agent = ureq::AgentBuilder::new().timeout(Duration::from_secs(8)).build();
            // DB-121/DB-123: the address is a function of the swap's mint blind (the custodians re-derive it
            // from the sealed blind and refuse any other). A swap recorded before the blind was chosen up front
            // has nothing to re-derive from and stays where it is.
            let reserve: Option<serde_json::Value> = match rec.mint_blind {
                Some(b) => agent
                    .post(&format!("{}/get_reserve_swap_address", node_url()))
                    .send_json(serde_json::json!({
                        "asset": rec.asset,
                        "d_blind_hex": hex::encode(usdmd_node::spend_frontier::digest_to_lane_bytes(&b)),
                    }))
                    .ok()
                    .and_then(|r| r.into_json().ok()),
                None => None,
            };
            if let Some(rj) = reserve {
                if rj.get("reserve_ready").and_then(|v| v.as_bool()).unwrap_or(false) {
                    rec.deposit_address = rj.get("deposit_address").and_then(|v| v.as_str()).unwrap_or("").to_string();
                    rec.threshold = rj.get("threshold").and_then(|v| v.as_u64()).unwrap_or(0);
                    rec.validators = rj.get("validators").and_then(|v| v.as_u64()).unwrap_or(0);
                    rec.status = "awaiting_deposit".to_string();
                }
            }
        }
    }
    let out = serde_json::to_value(&*rec).map_err(|e| e.to_string())?;
    write_swaps(&swaps);
    Ok(out)
}
off_ui_thread!(wallet_swap_status => wallet_swap_status_blocking(swap_id: String));

/// SWAP HISTORY — every swap this wallet initiated, newest first, so no swap is ever lost and each is locateable
/// by swap_id. Read fresh from disk (the source of truth), filtered to the open wallet.
