#[tauri::command]
async fn dapp_provider_height() -> serde_json::Value {
    node_status().await
}

#[tauri::command]
async fn dapp_provider_node_rpc(path: String, body: String) -> Result<serde_json::Value, String> {
    // Chain-data proxy for the dApp (blocks, tokens, pools, swaps). Wallet spends go through the approval-gated
    // commands (DB-373) — a remote page can never move funds here.
    //
    // ⛔ DB-373: the page chooses the path, so the proxy forwards ONLY chain-public reads. MEASURED 2026-10-03 (hole
    // scanner): it forwarded ANY route with the wallet's loopback trust — the node's own Letter inbox and identity, its
    // peer list, diagnostics, a note-ownership oracle and CPU-heavy bench routes were all one `request` away.
    let route = match path.split_once('?') {
        Some((r, _)) => r,
        None => path.as_str(),
    };
    if !DAPP_ALLOWED_NODE_READS.contains(&route) {
        return Err(format!("{route} is not a public chain read — apps cannot reach it through the wallet"));
    }
    node_rpc(path, body).await
}

/// DB-373 — the node routes an app may read through the wallet: chain-public facts every peer already holds. Nothing
/// keyed to this wallet or this node (inbox, identity, notes, peers, diagnostics, bench) is on it.
const DAPP_ALLOWED_NODE_READS: &[&str] = &[
    "/get_info",
    "/get_height",
    "/get_tip",
    "/dag_recent",
    "/json_rpc",
    "/group/resolve",
    "/dir/resolve",
    "/dir/profile",
    // spec §12.6: what creators chose to publish (an asset's name and picture, a collection's title, cover and pieces),
    // read from this wallet's own node's copy of the chain's directory
    "/dir/asset",
    "/dir/asset_art",
    "/dir/collection",
    "/dir/collections",
    "/resolve_username",
    "/names_of",
    "/amm_pool",
    "/book_level",
    "/reserves",
    "/get_solvency",
    "/get_governance",
    "/faucet/status",
    "/faucet/identity",
    // §BR-12 F13: the contract-state root and its transition ring — public chain words an app verifies its state against
    "/contract_state_root",
    "/contract_leaves_from",
];

/// The loopback port this wallet's own node serves its sites and their app routes on (`usdmd-node serve-sites`): 27752,
/// or the node's own `MONEROUSD_SOVEREIGN_PORT` (the variable `serve-sites` itself reads). A real-node rig sets it to
/// run its site host beside an installed wallet's (measured 2026-11-10: an installed wallet's site host had held 27752
/// on this machine for 22 days, so a check that needed that port could not start).
fn sovereign_port() -> u16 {
    std::env::var("MONEROUSD_SOVEREIGN_PORT").ok().and_then(|p| p.parse().ok()).unwrap_or(27752)
}

#[tauri::command]
async fn dapp_provider_api(path: String, body: String) -> Result<serde_json::Value, String> {
    // App-backend proxy: the launchpad apps' /api,/v1,/rpc routes are served by THIS wallet's own node on its
    // SOVEREIGN surface (:27752 serve-sites) — the node IS the backend (Pillar C, zero VPS). A framed clearnet
    // app routes every backend call here, so ion.monerousd.org reads the CHAIN, not the VPS. Read/query only;
    // a spend still routes through dapp_provider_transfer (the wallet's own auth gate).
    // DB-373: the app-backend proxy forwards ONLY the app-backend prefixes it exists for (a framed app already reaches its
    // own origin's /api directly; nothing else on the sovereign server is the wallet's to forward).
    let backend = ["/api/", "/v1/", "/rpc/", "/testnet/api/", "/mainnet/api/"].iter().any(|p| path.starts_with(p));
    if !backend {
        return Err(format!("{path} is not an app-backend route (/api, /v1, /rpc)"));
    }
    tauri::async_runtime::spawn_blocking(move || {
        let url = format!("http://127.0.0.1:{}{path}", sovereign_port());
        let agent = ureq::AgentBuilder::new().timeout(Duration::from_secs(8)).build();
        let result = if body.trim().is_empty() {
            agent.get(&url).call()
        } else {
            let json: serde_json::Value =
                serde_json::from_str(&body).map_err(|e| format!("bad request body: {e}"))?;
            agent.post(&url).send_json(json)
        };
        match result {
            Ok(resp) => resp.into_json::<serde_json::Value>().map_err(|e| format!("sovereign api non-JSON: {e}")),
            Err(ureq::Error::Status(code, resp)) => {
                let txt = resp.into_string().unwrap_or_default();
                Err(format!("sovereign api {code}: {txt}"))
            }
            Err(e) => Err(format!("sovereign api unreachable: {e}")),
        }
    })
    .await
    .map_err(|e| format!("dapp_provider_api task failed: {e}"))?
}

/// ⛔ ASYNC for the same reason as the tap-flow commands: this waits on a person at the auth prompt and
/// then runs a full WHIR spend prove and broadcast. As a synchronous command all of that sat on the main
/// thread, so the dApp page that requested the transfer froze solid for the entire approval — the one
/// moment a user most needs the interface to look alive.
///
/// Both halves run inside ONE blocking task so their order is unchanged and unchangeable: the auth gate
/// still resolves before a single byte of the send is built, and a refusal still returns before it.
#[tauri::command]
async fn dapp_provider_transfer(to: String, amount_usdm: f64) -> Result<serde_json::Value, String> {
    tauri::async_runtime::spawn_blocking(move || {
        // A spend requested by a remote dApp MUST clear the wallet's local auth gate first — never a
        // silent transfer.
        require_user_approval(format!(
            "A dApp asks to send {amount_usdm} USDm to {}",
            approval_short(&to, 18)
        ))?; // DB-373: fails closed, and names the recipient the page chose
        wallet_user_send_blocking(to, amount_usdm)
    })
    .await
    .map_err(|e| format!("dapp_provider_transfer task failed: {e}"))?
}

// ── WEBSITE CONNECT (`web3_bridge`): the wallet's OWN window drives the door; no website and no framed app reaches
//    these commands (they are granted to the `main` window only). Each one that gives a site anything asks the user in
//    the core's own prompt, with the site's name taken from the door's own record, never from the caller (DB-373). ──

/// The user pressed "Connect a website": the door opens for a few minutes for whichever site asks next.
#[tauri::command]
fn web3_arm() -> Result<serde_json::Value, String> {
    web3_bridge::arm(None)?;
    Ok(serde_json::json!({ "armed": true, "port": web3_bridge::PORT }))
}

/// The user's answer to one site's connection request. Approving asks in the core's own prompt, naming the site.
#[tauri::command]
async fn web3_decide(request: String, approve: bool, balances: bool) -> Result<serde_json::Value, String> {
    tauri::async_runtime::spawn_blocking(move || {
        if !approve {
            let origin = web3_bridge::decide(&request, None)?;
            return Ok(serde_json::json!({ "linked": false, "origin": origin }));
        }
        {
            let g = WALLET.lock().unwrap_or_else(|e| e.into_inner());
            g.as_ref().ok_or_else(|| "open your wallet first, then approve the site".to_string())?;
        }
        let (origin, _asked) = web3_bridge::waiting_site(&request).ok_or_else(|| "that connection request is no longer waiting".to_string())?;
        let also = if balances { format!(" and let it {}", web3_bridge::grant_words("balances").unwrap_or("see your balances")) } else { String::new() };
        require_user_approval(format!("Connect the website {origin} to this wallet{also}"))?;
        web3_bridge::decide(&request, Some(balances))?;
        Ok(serde_json::json!({ "linked": true, "origin": origin, "balances": balances }))
    })
    .await
    .map_err(|e| format!("web3_decide task failed: {e}"))?
}

/// Give a linked site its one grant ("balances"), or take it back. Giving asks in the core's own prompt.
#[tauri::command]
async fn web3_grant(origin: String, what: String, on: bool) -> Result<serde_json::Value, String> {
    tauri::async_runtime::spawn_blocking(move || {
        let words = web3_bridge::grant_words(&what).ok_or_else(|| "there is no such grant".to_string())?;
        if !web3_bridge::is_connected(&origin) {
            return Err("that site is not connected".into());
        }
        if on {
            require_user_approval(format!("Let the website {origin} {words} until you end its connection"))?;
        }
        web3_bridge::set_grant(&origin, &what, on)?;
        Ok(serde_json::json!({ "origin": origin, "what": what, "on": on }))
    })
    .await
    .map_err(|e| format!("web3_grant task failed: {e}"))?
}

/// The wallet page's answer to one request a site made through the door.
#[tauri::command]
fn web3_respond(id: String, ok: bool, result: serde_json::Value, error: String) {
    web3_bridge::respond(&id, if ok { Ok(result) } else { Err(error) });
}

/// The sites linked now and the connection requests still waiting, for the wallet's own list.
#[tauri::command]
fn web3_sites() -> serde_json::Value {
    let sites: Vec<serde_json::Value> = web3_bridge::linked_sites().into_iter().map(|(origin, balances)| serde_json::json!({ "origin": origin, "balances": balances })).collect();
    let waiting: Vec<serde_json::Value> =
        web3_bridge::waiting().into_iter().map(|(request, origin, app, balances)| serde_json::json!({ "request": request, "origin": origin, "app": app, "balances": balances })).collect();
    serde_json::json!({ "sites": sites, "waiting": waiting, "port": web3_bridge::PORT })
}

/// End one site's connection (the user's tap).
#[tauri::command]
fn web3_end(origin: String) {
    web3_bridge::end(&origin);
}

