// Browser navigation controls for the embedded webview (real page history, MetaMask/Electron-style).
#[tauri::command]
fn dapp_back<R: tauri::Runtime>(app: tauri::AppHandle<R>) -> Result<(), String> {
    use tauri::Manager;
    if let Some(wv) = app.get_webview(DAPP_WEBVIEW_LABEL) { wv.eval("history.back()").map_err(|e| e.to_string())?; }
    Ok(())
}

#[tauri::command]
fn dapp_forward<R: tauri::Runtime>(app: tauri::AppHandle<R>) -> Result<(), String> {
    use tauri::Manager;
    if let Some(wv) = app.get_webview(DAPP_WEBVIEW_LABEL) { wv.eval("history.forward()").map_err(|e| e.to_string())?; }
    Ok(())
}

#[tauri::command]
fn dapp_reload<R: tauri::Runtime>(app: tauri::AppHandle<R>) -> Result<(), String> {
    use tauri::Manager;
    if let Some(wv) = app.get_webview(DAPP_WEBVIEW_LABEL) { wv.reload().map_err(|e| e.to_string())?; }
    Ok(())
}

#[tauri::command]
fn dapp_navigate<R: tauri::Runtime>(app: tauri::AppHandle<R>, url: String) -> Result<(), String> {
    use tauri::Manager;
    let parsed: tauri::Url = url.trim().parse().map_err(|e| format!("bad url: {e}"))?;
    if !matches!(parsed.scheme(), "http" | "https") {
        return Err("only http(s) dApp URLs".into());
    }
    let wv = app.get_webview(DAPP_WEBVIEW_LABEL).ok_or("no dApp webview open")?;
    wv.navigate(parsed).map_err(|e| e.to_string())
}

#[tauri::command]
fn dapp_bounds<R: tauri::Runtime>(app: tauri::AppHandle<R>, x: f64, y: f64, w: f64, h: f64) -> Result<(), String> {
    // Desktop repositions the embedded child webview over `#browserViewport`; mobile's full-screen route needs no
    // bounds (no native child webview exists there), so this is a no-op on mobile.
    #[cfg(desktop)]
    {
        use tauri::{LogicalPosition, LogicalSize, Manager};
        if let Some(wv) = app.get_webview(DAPP_WEBVIEW_LABEL) {
            wv.set_position(LogicalPosition::new(x, y)).map_err(|e| e.to_string())?;
            wv.set_size(LogicalSize::new(w.max(1.0), h.max(1.0))).map_err(|e| e.to_string())?;
            wv.show().map_err(|e| e.to_string())?;
        }
    }
    #[cfg(not(desktop))]
    let _ = (&app, x, y, w, h);
    Ok(())
}

// Hide the embedded webview while the launchpad grid or another wallet tab shows (it stays created + keeps its
// page loaded; `dapp_show`/`dapp_bounds` reveal it again).
#[tauri::command]
fn dapp_hide<R: tauri::Runtime>(app: tauri::AppHandle<R>) -> Result<(), String> {
    // Desktop hides the embedded child webview; mobile's full-screen route is dismissed by the JS shell itself, so
    // there is nothing native to hide — no-op on mobile.
    #[cfg(desktop)]
    {
        use tauri::Manager;
        if let Some(wv) = app.get_webview(DAPP_WEBVIEW_LABEL) {
            wv.hide().map_err(|e| e.to_string())?;
        }
    }
    #[cfg(not(desktop))]
    let _ = &app;
    Ok(())
}

